class Solution {
    record Node(int start, int end){}

    public int eraseOverlapIntervals(int[][] intervals) {
        List<Node> nodes = new ArrayList();
        List<Node> result = new ArrayList();
        for(var interval: intervals)
            nodes.add(new Node(interval[0],interval[1]));
        nodes.sort(Comparator.comparingInt(Node::end).thenComparingInt(Node::start)); 
        int addedIntervals=0;
        result.add(nodes.get(0));      
        for(int i=1;i<nodes.size();i++){
            Node prevAdded = result.getLast();
            Node current = nodes.get(i);
            if(current.start < prevAdded.end){
                //skip
            } else{
                result.add(current);
            }
        }
        return nodes.size() - result.size();
    }
}

