class Solution {
    int m,n;
    int dp[][];
    String word1, word2;
    void initialize(String word1, String word2){
        this.word1= word1;
        this.word2= word2;
        m = word1.length();
        n = word2.length();
        dp = new int[m][n];
        for(var ar:dp)
            Arrays.fill(ar,-1);

    }
    // if match  x-1, y-1
    // if dont match x, y-1 + 1
    // if dont match x-1, y + 1

    // min of above3
    //base condition if x == -1 , return 0 , //empty string || y = -1


    int minDistanceIdx(int x, int y){

        if(x==-1 && y == -1){
            // System.out.println("x:" +x+" y:"+y+" -> "+  dp[x][y] );
            return 0;
        }
        if(x==-1)
            return y+1;
        if(y == -1) 
            return x+1; 
        if(dp[x][y]!=-1){
            // System.out.println("x:" +x+" y:"+y+" -> "+  dp[x][y] );
            return dp[x][y];
        }
        dp[x][y] = Math.max(m,n);
        // System.out.println("x:" +x+" y:"+y+" -> "+  dp[x][y] );
        if(word1.charAt(x) == word2.charAt(y))
            dp[x][y] = minDistanceIdx(x-1, y-1);
        else{
            dp[x][y] = Math.min(1+ minDistanceIdx(x, y-1), 1+ minDistanceIdx(x-1, y)) ;
            dp[x][y] = Math.min(dp[x][y] ,1+ minDistanceIdx(x-1, y-1)) ;
        } 
        return dp[x][y];
    }
    public int minDistance(String word1, String word2) {
        initialize(word1, word2);
        return minDistanceIdx(m-1, n-1);
    }
}

