record Node(int value, int minSoFar){}
class MinStack {
    Stack<Node> stack;

    public MinStack() {
        stack = new Stack<Node>();
    }

    public void push(int value) {
        if(stack.isEmpty()){
            stack.add(new Node(value,value));
            return;
        }
        stack.add(new Node(value, Math.min(value, getMin())));
    }

    public void pop() {
        stack.pop();
    }

    public int top() {
        return stack.peek().value();
    }

    public int getMin() {
        return stack.peek().minSoFar();
    }   
}

