course-schedule.code:
class Solution {
    Map<Integer,Set<Integer>> graph;
    int n;

    void initialize(int numCourses, int[][] prerequisites){
        n = numCourses;
        graph = new HashMap<>();
        for(int i=0;i<n;i++)
            graph.putIfAbsent(i, new HashSet<>());
        for(var dependecy:prerequisites){
            addEdge(dependecy[1],dependecy[0]);
        }
    }
    void addEdge(int x,int y){
        graph.putIfAbsent(x, new HashSet<>());
        graph.putIfAbsent(y, new HashSet<>());
        graph.get(x).add(y);
    }
    boolean isCycle(int x, Set<Integer> visited,Set<Integer> dfsStack){
        if(dfsStack.contains(x))
            return true;
        if(visited.contains(x))
            return false;
        visited.add(x);
        dfsStack.add(x);
        boolean hasCycle = false;   
        for(var y:graph.get(x)){
            hasCycle = hasCycle || isCycle(y,visited , dfsStack);
        }

        dfsStack.remove(x);
        return hasCycle;
    }
    public boolean canFinish(int numCourses, int[][] prerequisites) {

        initialize(numCourses,prerequisites); 
        boolean hasCycle = false;   
        Set<Integer> visited = new HashSet<>();
        Set<Integer> dfsStack = new HashSet<>();
        for(int i=0;i<n;i++)
            hasCycle = hasCycle || isCycle(i,visited , dfsStack);
        return !hasCycle;
    }
}

valid-parenthesis-string.code:
class Solution {
    int n;
    String s;
    Boolean dp[][];
    boolean checkValid(int idx, int stateSoFar){
        if(idx == n)
            return stateSoFar == 0;
        if(stateSoFar < 0)
            return false;
        if(dp[idx][stateSoFar]!=null)
            return dp[idx][stateSoFar]; //==1?true:false;
        if(s.charAt(idx) == '('){
            dp[idx][stateSoFar] = checkValid(idx+1,stateSoFar+1);

        } else if(s.charAt(idx) == ')'){
            dp[idx][stateSoFar] = checkValid(idx+1,stateSoFar-1);
        } else{
            dp[idx][stateSoFar] = checkValid(idx+1,stateSoFar) || checkValid(idx+1,stateSoFar+1) || checkValid(idx+1,stateSoFar-1) ;
        }
        return dp[idx][stateSoFar];
    }
    public boolean checkValidString(String s) {
        n = s.length();
        this.s = s;
        dp = new Boolean[n][n];
        for(int i=0;i<n;i++)
            Arrays.fill(dp[i], null);
       return checkValid(0,0);
    }
}

lowest-common-ancestor-of-a-binary-searc.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        TreeNode i = root;
        while(i!=null){
            boolean areSmaller = p.val <i.val && q.val<i.val;
            boolean areLarger = p.val >i.val && q.val>i.val;
            if(areSmaller)
                i= i.left;
            else if(areLarger)
                i = i.right;
            else 
                return i; // either p or q match OR both node belong to separate branches
        }
        return i;
    }
}

subsets.code:
class Solution {
    int n;
    List<List<Integer>> result = new ArrayList<>();
    int[] nums;
    void backtrack(int idx,List<Integer> subsetSoFar){
        if(idx==n){
            result.add(new ArrayList<>(subsetSoFar));
            return;
        }
        //take
        subsetSoFar.add(nums[idx]);
        backtrack(idx+1, subsetSoFar);

        //don't take, revert shared object subsetSoFar
        subsetSoFar.removeLast();
        backtrack(idx+1, subsetSoFar);

    }
    public List<List<Integer>> subsets(int[] nums) {
        n = nums.length;
        this.nums= nums;
        backtrack(0, new ArrayList<>());
        return result;
    }
}

