record VersionedValue(String value, int version){}
class TimeMap {
    Map<String, TreeSet<VersionedValue> > map;
    TreeSet<VersionedValue> tmp ;
    public TimeMap() {
        map = new HashMap<>();
        tmp = new TreeSet<VersionedValue>( (x,y) -> Integer.compare(x.version(),y.version()) );
    }

    public void set(String key, String value, int timestamp) {
        map.putIfAbsent(key, new TreeSet(tmp) );
        map.get(key).add(new VersionedValue(value,timestamp));
    }

    public String get(String key, int timestamp) {
        if(!map.containsKey(key))
            return "";
        VersionedValue v = map.get(key).floor(new VersionedValue("",timestamp));
        return v==null?"":v.value();
    }
}

