class Solution {
    public int reverseBits(int n) {
       int reversedBits = 0;
       for(int i=0;i<32;i++){
            reversedBits = reversedBits<<1;
            reversedBits =reversedBits |(n&1);
            n = n>>1;
       } 
       return reversedBits;
    }
}

top-k-frequent-elements.code:
record Record(int num, int freq){}
class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> countMap = new HashMap<>();
        Queue<Record> freqHeap = new PriorityQueue<Record>((x,y)-> {
            int freqCompare = Integer.compare(x.freq(),y.freq());
            return freqCompare == 0 ? Integer.compare(x.num(),y.num()) : freqCompare;
            }
        );
        for(var num:nums){
            countMap.putIfAbsent(num,0);       
            countMap.put(num, countMap.get(num)+1);
        }

        for(var num:countMap.keySet()){
            freqHeap.add(new Record(num,countMap.get(num)));
            // System.out.println(freqHeap);
            if(freqHeap.size() > k)
                freqHeap.poll();
        }
        int[] result = new int[k];
        for(int i=0;i<k;i++){
            int num= freqHeap.poll().num();
            result[i] = num;
        }
        return result;
    }
}

word-ladder.code:
record Node(String word, int steps){}
class Solution {
    Map<String, Set<String>> graph;
    List<String> allWords;
    void initialize(String beginWord, String endWord, List<String> wordList){
        graph = new HashMap<>();
        allWords = new ArrayList<>();
        allWords.addAll(wordList);
        allWords.add(beginWord);
        // allWords.add(endWord);
        for(var word:allWords)
            graph.putIfAbsent(word,new HashSet<>());
        for(var word:allWords){
            wordMutations(word);
        }
        // System.out.println(graph);

    }
    void wordMutations(String word){
        StringBuilder sb = new StringBuilder(word);
        for(int i=0;i<word.length();i++){
            for(char c ='a';c<='z';c++){
                if(c!=word.charAt(i)){
                    sb.setCharAt(i,c);
                    if(graph.containsKey(sb.toString()))
                        graph.get(word).add(sb.toString());
                    sb.setCharAt(i,word.charAt(i)); //unset
                }
            }
        }
    }


    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        initialize(beginWord,endWord,wordList);
        Queue<Node> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        queue.add(new Node(beginWord,1));
        while(!queue.isEmpty()){
            Node current = queue.poll();
            if(current.word().equals(endWord))
                return current.steps();
            if(visited.contains(current.word()))
                continue;
            // System.out.println(current + " adj:" + graph.get(current.word()));
            visited.add(current.word());
            for( var y: graph.get(current.word()))
                queue.add(new Node(y,current.steps()+1));
        }
        return 0;
    }
}

