class Solution {
    public int search(int[] nums, int target) {
        int start = 0;
        int end = nums.length -1;
        while(start<=end){
            int mid = (start+end)/2;
            if(nums[mid] == target)
                return mid;
            else if(target < nums[mid]) //go right 
                end = mid-1;
            else
                start = mid +1;

        }
        return -1;
    }
}

