n-queens.code:
class Solution {
    char[][] board;   
    int n;
    List<List<String>> result;

    List<String> getState(char[][] board){
        List<String> boardState = new ArrayList<>();
        for(int i=0;i<n;i++){
            StringBuilder sb = new StringBuilder("");
            for(int j=0;j<n;j++){
                sb.append(board[i][j]);
            }
            boardState.add(sb.toString());
        }
        return boardState;  
    }
    void initialize(int n){
        board = new char[n][n];
        this.n = n;
        for(int i=0;i<n;i++)
            Arrays.fill(board[i],'.');

        result = new ArrayList<>();
    } 
    boolean isValid(int x, int y){
        return x>=0 && x < n && y>=0 && y<n;
    }
    boolean checkDiagonals(int x, int y){
        int i=x+1;
        int j=y+1;
        //go dir 1
        while(isValid(i,j)){
            if(board[i][j] == 'Q')
                return false;
            i++;
            j++;
        }

        i=x-1;
        j= y-1;
        while(isValid(i,j)){
            if(board[i][j] == 'Q')
                return false;
            i--;
            j--;
        }

        i=x-1;
        j=y+1;
        while(isValid(i,j)){
            if(board[i][j] == 'Q')
                return false;
            i--;
            j++;
        }


        i= x+1;
        j= y-1;
        while(isValid(i,j)){
            if(board[i][j] == 'Q')
                return false;
            i++;
            j--;
        }
        return true;
    }
    boolean checkRow(int row){
        for(int i=0;i<n;i++){
            if(board[row][i] == 'Q')
                return false;
        }
        return true;
    }
    void traverseAndUpdate(int col){
        if(col==n){
            result.add(getState(board));
        }//reached end state successfully

        for(int i=0;i<n;i++){
            boolean isPlacementValid = checkRow(i) && checkDiagonals(i,col);
            if(isPlacementValid){
                board[i][col] = 'Q';//place
                traverseAndUpdate(col+1);
                board[i][col] = '.';//unplace
            } 
        }
    }
    public List<List<String>> solveNQueens(int n) {
        initialize(n);
        traverseAndUpdate(0);
        return result;
    }
}

jump-game.code:
class Solution {
    int[] nums;
    int n;
    Boolean[] dp;

    void initialize(int[] nums){
        this.nums = nums;
        this.n = nums.length;
        dp = new Boolean[n];
        Arrays.fill(dp,null);
    }
    boolean isReachable(int x){
        if(dp[x]!= null)
            return dp[x];
        if(x==n-1) 
            return true;

        dp[x] = false;
        for(int j=1;j<=nums[x] && (x+j)<n;j++){
            dp[x] = dp[x] || isReachable(x+j);
        }
        return dp[x];
    }
    public boolean canJump(int[] nums) {
        initialize(nums);
        return isReachable(0);

    }
}

jump-game-ii.code:
class Solution {
    int[] nums;
    int n;
    int[] dp;
    void initialize(int[] nums){
        this.nums = nums;
        this.n = nums.length;
        dp = new int[n];
        Arrays.fill(dp,-1);
    }
    int minSteps(int x){
        if(x==n-1)
            return 0;
        if(dp[x]!=-1)
            return dp[x];

        int minSteps = n;
        for(int j=1;j<=nums[x] && (x+j)<n;j++){
            minSteps = Math.min(minSteps, minSteps(x+j));
        }
        dp[x] =1+ minSteps;
        return dp[x];
    }
    public int jump(int[] nums) {
        initialize(nums);
        return minSteps(0);
    }
}

trapping-rain-water.code:
class Solution {
    public int trap(int[] height) {
        int n = height.length;
        int[] maxLeft = new int[n];
        int[] maxRight = new int[n];
        int maxLeftSoFar = 0;
        int maxRightSoFar = 0;
        for(int i=0;i<n;i++){
            maxLeft[i] =maxLeftSoFar;
            maxLeftSoFar = Math.max(maxLeftSoFar , height[i]);
        }
        for(int i = n-1;i>=0;i--){
            maxRight[i] = maxRightSoFar;
            maxRightSoFar = Math.max(maxRightSoFar , height[i]);
        }
        int totalWater = 0;
        for(int i=0;i<n;i++){
            // System.out.println(maxLeft[i]+" "+maxRight[i]);
            int currentWater = Math.min(maxLeft[i],maxRight[i]) - height[i];
            totalWater += (currentWater<0?0:currentWater);

            // System.out.println("totalWater:"+totalWater);
        }
        return totalWater;
    }
}

combination-sum.code:
class Solution {
    int[] candidates;
    int target; 
    int n;
    List<List<Integer>>[][] dp;
    void initialize(int[] candidates, int target){
        this.candidates =candidates; 
        this.target = target;
        this.n = candidates.length;
        dp = new ArrayList[n][target+1];
       for (int i = 0; i < n; i++) {
        for (int t = 0; t <= target; t++) {
            dp[i][t] = null;
            }
        }
    }
    List<List<Integer>> combinations( int target, int x){

        if(x==-1)
            return new ArrayList<>();
        if(target < 0 )
            return new ArrayList<>();

        //if empty is returned, we hit the result
        if(target == 0){
            List<List<Integer>> result = new ArrayList<>();
            result.add(new ArrayList<Integer>());
            return result;
        }

        // System.out.println("target:"+ target + " candidate:" +candidates[x] );
        if(dp[x][target]!=null){
            // System.out.println("Returning since combination exists:"+ dp[x][target]); 
            return dp[x][target];
        }

       //all the comb
        dp[x][target] = new ArrayList<>();
        List<List<Integer>> allCombos = new ArrayList<>(combinations( target - candidates[x],x));
        for(var combo:allCombos){
            if(combo!=null){
                var updatedCombo = new ArrayList<>(combo);
                updatedCombo.add(candidates[x]);
                dp[x][target].add(updatedCombo);
            }
        }
        dp[x][target].addAll(new ArrayList<>(combinations(target,x-1))) ;

        return dp[x][target];
    }
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        initialize(candidates,target);
        return combinations(target, n-1);
    }
}

binary-tree-right-side-view.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
 class Node{
    TreeNode node;
    int level;
    public Node(TreeNode node, int level){
        this.node = node;
        this.level = level;
    }
 }
class Solution {
    Queue<Node> q;
    void add(TreeNode x, int level){
        if(x == null)
            return;
        q.add(new Node(x,level));
    }
    public List<Integer> rightSideView(TreeNode root) {
        if(root == null)
            return new ArrayList<>();
        int currentLevel = 0;
        List<Integer> result = new ArrayList<>();
        int rightMostElement = 0;
        q = new LinkedList<>();
        add(root,0);
        while(!q.isEmpty()){
            Node x= q.poll();
            if(x.level == currentLevel){
                rightMostElement = x.node.val;
            }
            else{ //save when level chages
                currentLevel = x.level;
                result.add(rightMostElement);
                rightMostElement = x.node.val;
            }
            // add children
            add(x.node.left, x.level+1);
            add(x.node.right,x.level+1);
        }
        result.add(rightMostElement);
        return result;        
    }
}

