find-minimum-in-rotated-sorted-array.code:
class Solution {

    int getMinimum(int[] nums){


        int start = 0;
        int end = nums.length-1;
        int result = Integer.MAX_VALUE;
        while(start<=end){
            int mid= (start+end)/2;//left-biased

            // Check if the current mid is smaller than our best known minimum
            if (nums[mid] < result) {
                result = nums[mid];
            }

            if(nums[mid] <= nums[end]){
                end = mid-1;
            } else{
                start = mid+1;
            }
        }
        return result;
    }
    public int findMin(int[] nums) {
        return getMinimum(nums);
    }
}

merge-k-sorted-lists.code:
/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode mergeKLists(ListNode[] lists) {

        ListNode preHead =new ListNode(-1);
        ListNode result = preHead;
        PriorityQueue<ListNode> pq = new PriorityQueue<ListNode>((x,y) -> Integer.compare(x.val,y.val));
        for(var list:lists){
            if(list!=null)
                pq.add(list);
        }

        while(!pq.isEmpty()){
            ListNode current = pq.poll();

            result.next = current;
            current = current.next;
            if(current!=null)
                pq.add(current);
            result = result.next;
        }
        return preHead.next;
    }
}

