class Solution {
    public int longestConsecutive(int[] nums) {

        int maxSequence =0;

        HashSet<Integer> numsSet = new HashSet<>();

        for (int num : nums) {
            numsSet.add(num);
        }
        System.out.println(numsSet);
        for(int element: nums){
            int currentSequence = getSequenceLength(element, numsSet);
            maxSequence = Math.max(currentSequence,maxSequence);
        }
        return maxSequence;
    }
    int getSequenceLength(int element, HashSet<Integer> numsSet ){


        if(!numsSet.contains(element)){
            return 0;
        }
        int sequenceLength = 1;
        numsSet.remove(element);
        //expand right
        int nextElement = element+1;
        while(numsSet.contains(nextElement)){
            numsSet.remove(nextElement);
            nextElement++;
            sequenceLength++;
        }
        // System.out.println("Does not contain"+ nextElement);
        //expand left
        int previousElement = element-1;
        while(numsSet.contains(previousElement)){
            numsSet.remove(previousElement);
            previousElement--;
            sequenceLength++;
        }
        // System.out.println("Does not contain"+ previousElement);

        // System.out.println("Sequence length"+ sequenceLength);
        return sequenceLength;
    }
}

