class Solution {
    record Node(long start,long end){}
    public int findMinArrowShots(int[][] points) {
        List<Node> list = new ArrayList();
        //initialize
        for(int[] point:points){
            list.add(new Node(point[0],point[1]));
        }
        list.sort((x,y) -> {
            if(x.start ==  y.start)
                return Long.compare(x.end, y.end);
            return Long.compare(x.start, y.start);
        });
        int arrows = 0;
        long currentEnd = Long.MIN_VALUE;
        for(Node node:list){
            if(node.start <= currentEnd ){ //this is bursted by current arrow
                currentEnd = Math.min(currentEnd, node.end);// shrink the boundry for fully covered case (1-4),(2-3) 
            } else{
                currentEnd = node.end;
                arrows++;
            }
        }
        return arrows;
    }
}

