/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int maxDepth = 0;
    void traverse(TreeNode x, int depth){
        if(x == null)
            return;
        maxDepth = Math.max(maxDepth, depth); // current node processing
        traverse(x.left, depth+1);
        traverse(x.right, depth+1);
    }
    public int maxDepth(TreeNode root) {
        traverse(root,1);
        return maxDepth;
    }
}

lowest-common-ancestor-of-a-binary-tree.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */

class Solution {
    ArrayList<TreeNode> resultStack = null;
    void find(ArrayList<TreeNode> stackSoFar, TreeNode x, TreeNode toFind){
        if(x==null )
            return ;
        if(x == toFind){
            stackSoFar.add(x);    
            resultStack = new ArrayList(stackSoFar);
            return;
        }
        //process
        stackSoFar.add(x);
        find(stackSoFar,x.left, toFind);
        stackSoFar.removeLast();

        stackSoFar.add(x);
        find(stackSoFar,x.right,toFind);
        stackSoFar.removeLast();
        return;
    }
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        ArrayList<TreeNode> pStack ,qStack;
        find(new ArrayList(),root,p);
        pStack = resultStack;
        find(new ArrayList(),root,q);
        qStack = resultStack;

        TreeNode result = null;
        for(int i=0;i<Math.min(pStack.size(),qStack.size()) ;i++){
            if(pStack.get(i) == qStack.get(i))
                result = pStack.get(i);
            else
                break; 
        }
        return result;
    }
}

