class Solution {
    int[] xOffsets = {0,0,+1,-1};
    int[] yOffsets = {+1,-1,0,0};
    char[][] grid;
    boolean[][] visited;
    int m,n;
    int count;
    boolean isBounds(int x,int y){
        return x>=0 && x<m && y>=0 &&y<n;
    }

    void initialize(char[][] grid){
        this.grid =grid;
        m = grid.length;
        n = grid[0].length;
        visited = new boolean[m][n];
        count = 0;
    }
    void dfs(int x,int y){
        if(visited[x][y])
            return;
        visited[x][y] =true;
        for(int i=0;i<4;i++){
            int xChild = x + xOffsets[i];
            int yChild = y + yOffsets[i];
            if(isBounds(xChild, yChild) && grid[xChild][yChild]=='1'){
                    dfs(xChild,yChild);
            }
        }


    }
    public int numIslands(char[][] grid) {
        initialize(grid);
        for(int i=0;i<m;i++){
            for(int j=0; j<n; j++){
                if(grid[i][j] == '1' && !visited[i][j]){
                    dfs(i,j);
                    count++;
                }
            }
        }
        return count;
    }
}

find-peak-element.code:
class Solution {
    int[] nums;
    int n;
    long get(int i){
        if(i>=0 && i<n)
            return nums[i];
        return Long.MIN_VALUE;
    }
    public int findPeakElement(int[] nums) {
        //initialize
        this.nums = nums;
        n= nums.length;

        int s = 0;
        int e = n-1;
        while(s<=e){
            int mid = (s+e)/2;
            if(get(mid-1) < get(mid) && get(mid+1) < get(mid) )
                return mid;
            else if( get(mid-1) >= get(mid)) //go left
                e = mid-1;
            else
                s = mid+1;
        }
        return -1;
    }
}

