class Solution {
    int[][] matrix;
     int target;

    int getRow(){
        int row = -1;
        int start =0;
        int end = matrix.length -1;
        while(start<=end){
            int mid = (start +end)/2;
            if(target >= matrix[mid][0]){
                row = mid;
                start = mid+1; //better the row
            }
            else{
                end =mid -1;
            }
        }
        return row;
    }
    boolean exists(int[] row){
        int start =0;
        int end = row.length-1;
        while(start<=end){
            int mid = (start +end)/2;
            if(row[mid] == target)
                return true;
            else if(target <row[mid])
                end = mid-1;
            else
                start =mid +1;
        }
        return false;
    }
    public boolean searchMatrix(int[][] matrix, int target) {
        this.matrix = matrix;
        this.target = target;
        int row = getRow();
        if(row == -1)
            return false;
        return exists(matrix[row]);
    }
}

