class Trie {
    boolean isLeaf;
    HashMap<Character, Trie> adj;
    public Trie() {
        isLeaf = false;
        adj = new HashMap<>();
    }

    public void insert(String word) {
        Trie q = this;

        for(char c:word.toCharArray()){
            // System.out.println("inserting" + c);
            q.adj.putIfAbsent(c, new Trie());
            q = q.adj.get(c);
        }
        q.isLeaf= true;
    }

    public boolean search(String word) {
        Trie q = this;
        for(char c:word.toCharArray()){
            // System.out.println("searching" + c);

            if(!q.adj.containsKey(c)){
                return false;
            }
            q = q.adj.get(c);
        }
        return q.isLeaf;

    }

    public boolean startsWith(String prefix) {
        Trie q = this;
        for(char c:prefix.toCharArray()){
            if(!q.adj.containsKey(c)){
                return false;
            }
            q = q.adj.get(c);
        }
        return true;
    }
}

