remove-duplicates-from-sorted-list-ii.code:
/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if(head ==null || head.next ==null)
            return head;

        ListNode preHead = new ListNode(-101);
        ListNode r = preHead;
        int preState = head.val;

        ListNode q = head;
        int ongoingState = preHead.val;
        while(q!=null){
            boolean isLast = q.next==null?true:q.val!=q.next.val;
            if(isLast){
                boolean isDuplicate = q.val == ongoingState;
                if(!isDuplicate){
                    r.next = q;
                    r = r.next;  
                } 
            }
            ongoingState = q.val;
            q=q.next;
            r.next=null; //important to mark last node 
        }

        return preHead.next;
    }
}

reverse-nodes-in-k-group.code:
/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */

// record Pointers(ListNode head, ListNode tail){}
class Solution {
    int k;
    void reverseList(ListNode head, ListNode tail){
        // ListNode preHead = new ListNode(-1);
        ListNode p = null;
        ListNode q = head;
        ListNode newHead = head; 
        ListNode tailNext =tail.next;
        while(q!=tailNext ){

            ListNode tmp = q.next;
            q.next = p; //reverse
            newHead = q;
            p = q;
            q = tmp;
        }

    }

    ListNode getNextKTail(ListNode head){
        int count = 1;
        ListNode q = head;
        while(count<k && q!=null){
            q = q.next;
            count++; //count becomes k
        }
        return q;
    }
    public ListNode reverseKGroup(ListNode head, int k) {
        this.k = k;
        ListNode preHead = new ListNode(-1);
        ListNode headK = head;
        ListNode prevTailK =  preHead;

        while(headK!=null){
            ListNode tailK =  getNextKTail(headK);
            if(tailK == null)
                break;
            ListNode tailKNext = tailK.next;

            reverseList(headK,tailK);
            ListNode newHeadK = tailK;
            ListNode newTailK = headK; //after reversal

            prevTailK.next = newHeadK;
            newTailK.next  = tailKNext;
            prevTailK = newTailK;
            headK = tailKNext;
        }
        return preHead.next;
    }
}

