class Solution {
    int[] dp;
    int n;
    int[] nums;
    void initialize(int[] nums){
        this.nums = nums;
        this.n = nums.length;
        // System.out.println("initializing:" + n);
        dp = new int[n];
        Arrays.fill(dp,-1);
    }
    int maxRobTill(int x){
        // System.out.println(x);
        if(x==-1 || x==-2)
            return 0;
        if(dp[x]!=-1)
            return dp[x];
        dp[x] = Math.max(
            nums[x] + maxRobTill(x-2),//take
            maxRobTill(x-1)//dont take
        );
        return dp[x];
    }
    public int rob(int[] nums) {
        initialize(nums);
        return maxRobTill(n-1);
    }
}

