class Solution {
    int getInt(char c){
        Map<Character,Integer> map= Map.of(
        'I',1,
        'V',5,
        'X',10,
        'L',50,
        'C',100,
        'D',500,
        'M',1000
        );
        return map.get(c);
    }
    public int romanToInt(String s) {
        int n =s.length();
        int result = 0;
        int prevInt = getInt(s.charAt(n-1));
        result = prevInt;
        for(int i=n-2;i>=0;i--){
            int currentInt = getInt(s.charAt(i));
            if(currentInt < prevInt)
                result-=currentInt;
            else{
                result+=currentInt;
            }
            prevInt = currentInt;
        }
        return result;  
    }
}

