zigzag-conversion.code:
class Solution {

    public String convert(String s, int numRows) {
        int n = s.length();
        char state ='f';
        int currentRow = 0;
        int numCols = n;
        char[][] result = new char[numRows][numCols];
        if(numRows == 1)
            return s;
        for(int i=0;i<n;i++){
            result[currentRow][i] = s.charAt(i);
            if(state =='f'){
                if( (currentRow+1) == numRows)//switch
                    state ='r';

            } else if(state =='r'){
                if((currentRow-1) == -1){//switch
                    state ='f';
                }
            }

            if(state =='f')
                currentRow++;
            else
                currentRow--;

        }
        StringBuilder sb = new StringBuilder("");
        for(int i=0;i<numRows;i++){
            for(int j=0;j<n;j++)
            if(result[i][j]!='\0')
                sb.append(result[i][j]);
        }
        return sb.toString();
    }
}

