class Solution {
    public boolean isSubsequence(String s, String t) {
        if(s.isEmpty())
            return true;

        int j = 0;
        char state = s.charAt(0);
        for(char c:t.toCharArray()){
            if(state == c){
                j++;
                if(j==s.length())
                    return true;
                state = s.charAt(j);
            }
        }
        return false;
    }
}

