class Solution {
    public int maxArea(int[] height) {
        int s =0;
        int e = height.length-1;
        int maxArea = 0;
        while(s<e){
            if(height[s] < height[e]){
                maxArea = Math.max(maxArea,(e-s)*height[s]);
                s++;
            }
            else{
                maxArea = Math.max(maxArea,(e-s)*height[e]);
                e--;
            }
        }
        return maxArea;
    }
}

minimum-window-substring.code:
class Window{
    int i,j;
    public Window(int i,int j){
        this.i = i;
        this.j =j ;
    }
    boolean isSmallerThan(Window y){
        return (this.j - this.i) < (y.j - y.i);
    }
    boolean equals(int i,int j){
        return this.i ==i && this.j==j;
    }
    public String toString(){
        return "i:"+i+" j:"+j ;
    }
}
class Solution {
    Map<Character,Integer> map;
    void createMap(String t){
        map = new HashMap();
        for(char c:t.toCharArray()){
            map.putIfAbsent(c,0);
            map.put(c, map.get(c)+1);
        }

    }
    public String minWindow(String s, String t) {
        createMap(t);
        var currentMap = new HashMap<Character,Integer>(); 
        int matched = 0;
        int start = 0;
        int end = -1;
        int n = s.length();
        Window minWindow = new Window(0,n);


        for(int i=0;i<s.length();i++){
            char c = s.charAt(i);
            currentMap.putIfAbsent(c,0);
            currentMap.put(c, currentMap.get(c) +1);
            if(map.containsKey(c)){//matching
                //increase matched only if we did not exaust characters in t yet
                if(currentMap.get(c) <= map.get(c))
                    matched++;
                //if more characters than exausted simply ignore
            } 
            // System.out.println( 
            // System.out.println("till character:"+ c +" matched is:" + matched + " i:"+i);
            if(matched == t.length()){
                end = i;
                //string found , update 
                Window currentWindow = new Window(start,end);


                //shrink window till matched -1
                while(matched == t.length() && start<=end){
                    if(currentWindow.isSmallerThan(minWindow))
                        minWindow = currentWindow;
                    char startChar = s.charAt(start);
                    int deleteCharCount = currentMap.get(startChar);
                    if(map.containsKey(startChar) && deleteCharCount <= map.get(startChar) ){ //deleting character will impact matched
                        matched--;
                    }
                    currentMap.put(startChar,currentMap.get(startChar)-1);
                    start++;   
                    currentWindow = new Window(start,end);    

                }
                // System.out.println("min window:"+minWindow);
            }


        }


        return minWindow.equals(0,n)?"":s.substring(minWindow.i,minWindow.j+1);
    }
}

