class Solution {
    char[][] board;
    boolean isInt(char c) {
         return c>='1' && c<='9';
    }
    boolean isColumnValid(int x){
        Set<Character>  set = new HashSet<>();

        for(int i=0;i<9;i++){
            char c = board[i][x];
            if(isInt(c) && set.contains(c))
                return false;
            set.add(c);
        }
        return true;
    }
    boolean isRowValid(int x){
        Set<Character>  set = new HashSet<>();

        for(int i=0;i<9;i++){
            char c = board[x][i];
            if(isInt(c) && set.contains(c))
                return false;
            set.add(c);
        }
        return true;
    }

    boolean isBoxValid(int x){
        int startx, starty, endx,endy;
        int row = x/3;
        int col = x%3;
        startx = row*3;
        starty = col*3;
        endx = startx +3;  
        endy = starty+3;  

        Set<Character>  set = new HashSet<>();
        for(int i=startx;i<endx;i++){
            for(int j=starty;j<endy;j++){
                char c = board[i][j];
                if(isInt(c) && set.contains(c))
                    return false;
                set.add(c);
            }
        }
        return true;
    }
    public boolean isValidSudoku(char[][] board) {
        this.board = board;
        for(int i=0;i<9;i++){
            if(!isColumnValid(i))
                return false;
            if(!isRowValid(i))
                return false;
            if(!isBoxValid(i))
                return false;
        }
        return true;
    }
}

