reverse-integer.code:
class Solution {
    List<Integer> getDigitList(int x){
        List<Integer> digits = new ArrayList<>();
        while(x!=0){
            int xMod = Math.abs(x%10);
            digits.add(xMod);
            x=x/10;
        }
        return digits;
    }
    public int reverse(int x) {
        var digitsMAX = getDigitList(Integer.MAX_VALUE).reversed();
        var digitsMIN = getDigitList(Integer.MIN_VALUE).reversed();
        int reversedInt = 0;

        int i=0;
        int multiplier = x<0 ?-1:1;
        var boundDigits = x<0 ?  digitsMIN : digitsMAX;
        int digitLength = (int) Math.pow(10,boundDigits.size()-1);
        // System.out.println(digitLength);
        boolean isCorner = x/digitLength>=1 || x/digitLength <=-1 ;
        while(x!=0){
            reversedInt = reversedInt*10; 
            int xMod = Math.abs(x%10);
            // System.out.println(xMod+" "+boundDigits.get(i));
             if(xMod > boundDigits.get(i) && isCorner){

                return 0;
            }
            if(xMod < boundDigits.get(i))
                isCorner = false;
            // System.out.println(xMod);
            reversedInt = reversedInt + xMod;
            x=x/10;
            i++;
        }

        return multiplier*reversedInt;
    }
}

