class Solution {
    int[] coins;
    int n;
    int[][] dp;
    void initialize(int amount, int[] coins){
        this.coins = coins;
        this.n = coins.length;
        dp = new int[n][amount+1];
        for(int i=0; i<n;i++)
            Arrays.fill(dp[i],-1);
    }
    int combinations(int amountLeft, int x){

        if(amountLeft<0)
            return 0;
        if(amountLeft==0)
            return 1; //found a way;
        if(x==-1)
            return 0;
        if(dp[x][amountLeft]!=-1)
            return dp[x][amountLeft];

        dp[x][amountLeft] = combinations(amountLeft - coins[x], x) //include this and continue
            + combinations(amountLeft, x-1);//dont include this

        return dp[x][amountLeft];
    }
    public int change(int amount, int[] coins) {
        initialize(amount,coins);
        return combinations(amount,n-1);
    }
}

