rotate-array.code:
class Solution {
    void reverse(int[] nums, int start , int end){
        int i = start;
        int j=end;
        while(i<j){
            //swap
            int tmp = nums[i];
            nums[i] = nums[j];
            nums[j] = tmp;

            i++;
            j--;
        }
    }
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k% n;
        reverse(nums,0,n-1);
        reverse(nums,0,k-1);
        reverse(nums,k,n-1);
    }
}

