class Solution {

    public double myPow(double x, int n) {
        if(n==0)
            return (double)1;
        if(n==1)
            return x;
        if(n==-1)
         return 1/x;


        double result = myPow(x,Math.abs(n/2));
        if (n>=0){
            if(n%2 == 0)
                return result*result;
            else 
                return result*result*x;
        } else{
            if(n%2 == 0)
                return 1/(result*result);
            else 
                return 1/(result*result*x);
        }
    }
}

