class Solution {
    int[][] dp;
    int[][] obstacleGrid;
    int m,n;
    void initialize(int[][] obstacleGrid){

        this.obstacleGrid = obstacleGrid;
        m = obstacleGrid.length;
        n = obstacleGrid[0].length;
        dp = new int[m][n];
        for(int i=0;i<m;i++)
            Arrays.fill(dp[i],-1);
    }
    boolean isValid(int x,int y){
        return x>=0 && x<m && y>=0 && y<n && obstacleGrid[x][y]==0;
    }
    int possiblePaths(int x, int y){
        if(!isValid(x,y))
            return 0;
        if(dp[x][y]!=-1)
            return dp[x][y];
        if(x==m-1 &&  y==n-1 && isValid(x,y))
            return 1;    
        dp[x][y] = 0;

        if(isValid(x+1,y)){
            dp[x][y]+=possiblePaths(x+1,y);
        }
        if(isValid(x,y+1)){
            dp[x][y]+=possiblePaths(x,y+1);
        }

        return dp[x][y];
    }
    public int uniquePathsWithObstacles(int[][] obstacleGrid) {
        initialize(obstacleGrid);
        return possiblePaths(0,0);
    }
}

