class Solution {
    char[][] board;
    int m,n;
    int[] xOffsets = {0,0,1,-1};
    int[] yOffsets = {1,-1,0,0};
    boolean[][] visited;
    boolean isSurrounded;

    void initialize(char[][] board){
        this.board = board;
        m = board.length;
        n = board[0].length;
        visited = new boolean[m][n];
        isSurrounded = true;
    }
    boolean isEdgeNode(int x,int y){
        return x==0 || x==m-1 || y==0 || y==n-1;
    }
    void dfs(int x, int y){

        if(isEdgeNode(x,y)){
            isSurrounded = false;
            return;
        }
        if(visited[x][y]){
            if(isEdgeNode(x,y))
                isSurrounded = false;
            return;
        }
        visited[x][y] =true;


        for(int i=0;i<4;i++){
            int xChild = x+xOffsets[i];
            int yChild = y+yOffsets[i];
            if(isValid(xChild, yChild) && board[xChild][yChild] == 'O')
                dfs(xChild, yChild);
        } 
    }
    boolean isValid(int x, int y){
        return x>=0 && x<m && y>=0 && y<n;
    }
    void mark(int x, int y){
        if(!isValid(x,y) || board[x][y] != 'O')
            return;




        board[x][y] = 'X';
        for(int i=0;i<4;i++){
            mark(x+xOffsets[i], y+yOffsets[i]);
        }
    }
    public void solve(char[][] board) {
        initialize(board);
        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                isSurrounded = true;
                if(board[i][j] == 'O' && !visited[i][j]){
                    dfs(i,j);
                    if(isSurrounded)
                        mark(i,j);
                }
            }
        }
    }
}

