    int minimumPathSum(int x,int y){
        if(x==n || y==n)
            return 0;

        if(dp[x][y]!=Integer.MIN_VALUE)
            return dp[x][y];

        dp[x][y] = triangle.get(x).get(y) +  Math.min(minimumPathSum(x+1,y) , minimumPathSum(x+1,y+1));
        return dp[x][y];
    }
    public int minimumTotal(List<List<Integer>> triangle) {
        n = triangle.size();
        this.triangle = triangle;
        initialize();
        return minimumPathSum(0,0);
    }
}

