class Solution {
    List<List<Integer>> result;
    int[] nums;
    int n;
    void swap(int x,int y,List<Integer> nums){
        int tmp = nums.get(x);
        nums.set(x, nums.get(y));
        nums.set(y,tmp);
    }
    void permute(int fromIndex, List<Integer> nums){
        // System.out.println("fromIndex:"+ fromIndex);
        if(fromIndex == n-1){
            // System.out.println("nums:" + nums);
            result.add(new ArrayList<>(nums));
            return;
        }

        for(int i=fromIndex;i<n;i++){
            swap(fromIndex,i,nums);
            permute(fromIndex+1,nums);
            swap(fromIndex,i,nums);
        }
    }
    public List<List<Integer>> permute(int[] nums) {
        this.nums= nums;
        n = nums.length;
        result = new ArrayList<>();
        permute(0, Arrays.stream(nums).boxed().collect(Collectors.toList()));
        return result;
    }
}

search-in-rotated-sorted-array.code:
class Solution {
    int[] nums;
    boolean inBounds(int start,int target,int end){
        return nums[start] <= target && target <= nums[end];
    }
    public int search(int[] nums, int target) {
        int start =0;
        this.nums = nums;
        int end = nums.length - 1;
        while(start<=end){
            int mid = (start+end)/2;
            if(nums[mid] == target)
                return mid;
            if(nums[start] <= nums[mid]){
                if(inBounds(start,target, mid)){
                    end = mid-1;
                }
                else{
                    start = mid+1;
                }
            } else{
                if(inBounds(mid,target, end)){
                    start = mid+1;
                }
                else{
                    end = mid -1;
                }
            }
        }
        return -1;
    }
}

