class Solution {
    public int rangeBitwiseAnd(int left, int right) {
        if(left==right)
            return left;
        int shifted = 0;
        while(true){
            if(left ==right)
                break;
            left = left>>1;
            right = right>>1;
            shifted++;
        }   

        for(int i=0;i<shifted;i++){
            left = left<<1;
        }

        return left;
    }
}

