/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode partition(ListNode head, int x) {
        if(head ==null)
            return head;

        ListNode smallerHead = new ListNode(-101);
        ListNode largerHead = new ListNode(-101);

        ListNode sq = smallerHead;
        ListNode lq = largerHead;
        ListNode q = head;
        while(q!=null){
            if(q.val<x){
                sq.next = q;
                sq = sq.next;
                q=q.next;
                sq.next = null;
            } else{
                lq.next = q;
                q=q.next;
                lq=lq.next;
                lq.next = null;
            }

        } 

        sq.next = largerHead.next;
        return smallerHead.next;
    }
}

