        Arrays.fill(dp,-1);
        return (int)waysTile(n);    
    }
}

maximum-level-sum-of-a-binary-tree.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    List<Integer> result;
    void traverse(TreeNode x,int level){
        if(x==null)
            return;
        if(level >= result.size())
            result.add(0);

        result.set(level,result.get(level) + x.val);
        traverse(x.left,level+1);
        traverse(x.right,level+1);

    }
    public int maxLevelSum(TreeNode root) {
        result = new ArrayList();
        result.add(Integer.MIN_VALUE);
        int maxLevel=0;
        traverse(root,1);
        for(int i=0;i<result.size();i++){
            if(result.get(i) > result.get(maxLevel))
                maxLevel = i;
        }

        return maxLevel;
    }
}

