/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    int getCount(ListNode head){
        ListNode q = head;
        int count=0;
        while(q!=null){
            count++;
            q=q.next;
        }
        return count;
    }
    ListNode reverse(ListNode head){
        ListNode p = head;
        ListNode q = head.next;
        p.next = null;
        ListNode reverseHead = head;
        while(p!=null && q!=null){
            ListNode tmp = q.next;
            q.next = p;

            reverseHead = q; 
            //next iter increment
            p = q;
            q = tmp;
        }
        return reverseHead;
    }
    ListNode traverseX(ListNode head,int x){ //get 3rd Node
        ListNode q = head;
        for(int i=1;i<x;i++){
            q = q.next;
        }
        return q;
    }

    public int pairSum(ListNode head) {
        int count = getCount(head);
        int middle = count/2;
        ListNode midHead =  traverseX(head,middle+1);
        midHead = reverse(midHead);
        ListNode p = head;
         ListNode q = midHead;
         int maxSum = 0;
        for(int i=0;i<middle;i++){
            maxSum = Math.max(maxSum,p.val+q.val);
            p = p.next;
            q=q.next;
        }
        return maxSum;
    }
}

