total-cost-to-hire-k-workers.code:
class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        int minHeap1Idx= -1;
        int minHeap2Idx= n;


        PriorityQueue<Integer> minHeap1 =new PriorityQueue();
        PriorityQueue<Integer> minHeap2 =new PriorityQueue();
        //fill heaps 
        for(int i=0;i<candidates;i++){
            minHeap1.add(costs[++minHeap1Idx]);
        }

        for(int i=0;i<candidates;i++){
            if((minHeap2Idx-1)>minHeap1Idx)
                minHeap2.add(costs[--minHeap2Idx]);
            else{
                break;
            }
        }
        long totalCost =0;
        int hired =0;
        while(hired!=k){
            if(minHeap1.isEmpty() || minHeap2.isEmpty())
                break;
            if( minHeap1.peek()<=minHeap2.peek()){
                totalCost+= minHeap1.poll(); 
                //readd in heap
                if(minHeap1Idx+1 < minHeap2Idx)
                    minHeap1.add(costs[++minHeap1Idx]);
            } else{
                totalCost+= minHeap2.poll(); 
                //readd in heap
                if(minHeap1Idx < (minHeap2Idx-1))
                    minHeap2.add(costs[--minHeap2Idx]);
            }
            hired++;
        }   
        //remaining     
        while(hired!=k && !minHeap1.isEmpty()){
               totalCost+= minHeap1.poll(); 
                //readd in heap
                if(minHeap1Idx+1 < minHeap2Idx)
                    minHeap1.add(costs[++minHeap1Idx]);

                hired++;
        }
        while(hired!=k && !minHeap2.isEmpty()){
                   totalCost+= minHeap2.poll(); 
                //readd in heap
                if(minHeap1Idx < (minHeap2Idx-1))
                    minHeap2.add(costs[--minHeap2Idx]);
                hired++;
        }

        return totalCost;
    }
}

reorder-routes-to-make-all-paths-lead-to.code:
class Solution {
    int n;
    List<HashMap<Integer,Integer>> graph;
    boolean[] visited;//added to the queue
    void populateGraph(int n, int[][] connections){
        this.n = n;
        graph = new ArrayList();
        visited = new boolean[n];
        for(int i=0;i<n;i++)
            graph.add(new HashMap());
        for(var connection:connections){
            int i = connection[0];
            int j = connection[1];
            graph.get(i).put(j,1);//straight
            graph.get(j).put(i,-1);//reversed
        }
    }

    public int minReorder(int n, int[][] connections) {
        Queue<Integer> q= new LinkedList();
        populateGraph(n,connections);
        q.add(0);
        visited[0] = true;
        int switches=0;
        while(!q.isEmpty()){

            int x= q.poll();
            // System.out.println("traversing:" + x);
            // System.out.println("children:" + graph.get(x));

            for(int y:graph.get(x).keySet()){
                if(!visited[y]){
                    if(graph.get(x).get(y) == 1)
                        switches++;
                    q.add(y);
                    visited[y] = true;
                }
            }
        }
        return switches;
    }
}

maximum-subsequence-score.code:
class Solution {
    record Node(int value, int index){};
    List<Node> getSorted(int[] nums){
        List<Node> nodes = new ArrayList<>();
        for(int i=0;i<nums.length;i++)
            nodes.add(new Node(nums[i],i));
        nodes.sort((x,y) -> y.value - x.value);
        return nodes;
    }
    public long maxScore(int[] nums1, int[] nums2, int k) {
        long cumulitiveAddition =0;
        long result =0;
        List<Node> nodes= getSorted(nums2);
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for(Node node:nodes){
            int currMultiple = node.value;
            int index = node.index;

            if(minHeap.size() == k){
                //pop and add
                if(nums1[index] > minHeap.peek()){
                    cumulitiveAddition = cumulitiveAddition - minHeap.poll();
                    cumulitiveAddition = cumulitiveAddition + nums1[index];
                    minHeap.add(nums1[index]);     
                }
                // System.out.println("cumulitiveAddition:"+cumulitiveAddition + " currMultiple:"+ currMultiple);
            } else {
                cumulitiveAddition = cumulitiveAddition + nums1[index];
                minHeap.add(nums1[index]);     
            }

            if(minHeap.size() == k)
                result = Math.max(result,cumulitiveAddition*currMultiple);

            // System.out.println("cumulitiveAddition:"+cumulitiveAddition + " currMultiple:"+ currMultiple+ " total:" + cumulitiveAddition*currMultiple + " minheap size" + minHeap.size() );
        }
        return result;
    }
}

