class Solution {
    Stack<Character> stack ; 
    void push(List<Character> result){
        for(char c:result)
            stack.add(c);
    }
    List<Character> process(){
        List<Character> result = new ArrayList<Character>();
        while(stack.peek()!='['){
            result.add(stack.pop());
        }
        stack.pop();
        String multipleString ="";
        while(!stack.empty() && stack.peek()>='0' && stack.peek()<='9'){
            multipleString = stack.pop() + multipleString;
        }
        int multiple = Integer.parseInt(multipleString);
        Collections.reverse(result);
        List<Character> resultMultiple = new ArrayList<Character>();
        for(int i=0;i<multiple;i++){
            resultMultiple.addAll(result);
        }
        return resultMultiple;
    }
    String convertStackToString(){
        StringBuilder sb =new StringBuilder("");
        while(!stack.empty()){
            sb.append(stack.pop());
        }
        return sb.reverse().toString();
    }
    public String decodeString(String s) {
        stack = new Stack<>();
        for(char c:s.toCharArray()){
            if(c==']'){
                //process
                push(process());
            }
            else {
                stack.add(c);
            }
        }
        return convertStackToString();
    }
}

asteroid-collision.code:
class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        Stack<Integer> stack = new Stack<>();
        for(int asteroid:asteroids){
            boolean bothExplode =false;
            while(!stack.empty()){
                bothExplode = false;
                if(stack.peek()>0 && asteroid<0){
                    if(Math.abs(asteroid) == stack.peek()){
                        stack.pop();
                        bothExplode =true;
                        break;
                    }
                    else if(Math.abs(asteroid) > stack.peek()){
                        stack.pop();

                    } else{
                        //destroy asteroid(dont push) and break;
                        break;
                    }
                } else {
                    stack.add(asteroid);
                    break;
                } 
            }
            if(stack.empty()&& !bothExplode)
                stack.add(asteroid);
        }
        int n = stack.size();
        int[] result = new int[n];
        for(int i=n-1;i>=0;i--){
            result[i] =stack.pop();
        }
        return result;
    }
}

