string-compression.code:
class Solution {
    int encode(char[] chars){
        char state = chars[0];
        int count = 1;
        int index = 1;
        for(int i=1;i<chars.length;i++){

            if(chars[i]!=state){//state changed
                if(count!=1){
                    String digits = "" + count;
                    for(char digit:digits.toCharArray())
                        chars[index++] = digit;
                    // chars[index] = (char)('0' + count);
                }
                count =1;
                state = chars[i];
                chars[index++] = chars[i];
            } 
            else{
                count++;
            }
        }

        //push final state count
        if(count!=1){
            String digits = "" + count;
            for(char digit:digits.toCharArray())
                chars[index++] = digit;
        }
        return index;
    }
    int compressBlanks(char[] chars){
        int nonBlankCount = 0;
        for(int i=0;i<chars.length;i++){
            if(chars[i] != '.'){
               nonBlankCount++;
               if((nonBlankCount-1)!=i){
                chars[nonBlankCount -1] = chars[i];
               }
            }
        }
        return nonBlankCount;
    }
    public int compress(char[] chars) {
        return encode(chars);
        // return compressBlanks(chars);
    }
}

greatest-common-divisor-of-strings.code:
class Solution {
    List<String> getPrefixes(String s){
        List<String> prefixes = new ArrayList<>();
        String prefix ="";
        for(char c:s.toCharArray()){
            prefix+=c;
            prefixes.add(prefix);
        }
        return prefixes;
    }
    boolean isDivisible(String s, String t){

        if(s.length()%t.length()!=0)
            return false;

        int multiple = s.length()/t.length();
        String multipleT = "";
        for(int i=0;i<multiple;i++){
            multipleT+=t;
        }
        return s.equals(multipleT);
    }
    public String gcdOfStrings(String str1, String str2) {
        String smallerString = str1.length() <= str2.length() ? str1:str2;
        String largerString = smallerString.equals(str1)?str2:str1;
        List<String> prefixes = getPrefixes(smallerString);
        String gcdPrefix = "";
        for(String prefix:prefixes){
            if(isDivisible(smallerString,prefix) && isDivisible(largerString,prefix))
                gcdPrefix = prefix;
        }
        return gcdPrefix;
    }
}

