maximum-number-of-vowels-in-a-substring-.code:
class Solution {
    public int maxVowels(String s, int k) {
        int maxVowels =0;
        Set<Character> vowelSet = Set.of('a','e','i','o','u');
        int startIdx = 0;
        int currVowel = 0;
        for(int i=0;i<s.length();i++){
            char c = s.charAt(i);
            if(i-startIdx+1 > k){ //window overflow, need to shift
                char prevC = s.charAt(startIdx);
                if(vowelSet.contains(prevC))
                    currVowel--;    
                startIdx++;
            }
            if(vowelSet.contains(c)){
                currVowel++;
            }
            maxVowels = Math.max(maxVowels,currVowel);
        }        
        return maxVowels;
    }
}

delete-node-in-a-bst.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    record Result(TreeNode parent, TreeNode node, boolean isLeft){}

    // avoid global varaibles , since recursive
    TreeNode parent;
    TreeNode node;
    boolean isLeft;

    void traverseAndFindParent(TreeNode x, int key){
        if(x == null)
            return;
        if(x.left!=null && x.left.val==key){
            isLeft = true;
            node = x.left;
            parent = x;
            return;
        }
        if(x.right!=null && x.right.val==key){
            isLeft=false;
            node = x.right;
            parent = x;
            return;
        }
        traverseAndFindParent(x.left,key);
        traverseAndFindParent(x.right,key);

    }
    Result find(TreeNode root, int key){
        traverseAndFindParent(root,key);
        return new Result(parent,node,isLeft);
    }
    int getSucessor(TreeNode x){
        TreeNode q = x.right;
        while(q.left!=null){
            q=q.left;
        }
        return q.val;
    }

    public TreeNode deleteNode(TreeNode root1, int key) {
        TreeNode root = new TreeNode(-1);//sentinal
        root.left =root1; 
        // System.out.println("Deleting:" + key);
        Result result = find(root,key);
        //convert to local variables, local copies of recursion variables
        TreeNode parent = result.parent;
        TreeNode node = result.node;
        boolean isLeft = result.isLeft;
        if(parent ==null)
            return root.left;
        System.out.println("Parent found:" + parent.val);

        boolean isLeaf = node.left ==null && node.right ==null;
        if(isLeaf){
            System.out.println("isLeaf is true");
            if(isLeft)
                parent.left = null;
            else
                parent.right =null;
            return root.left;
        }

        boolean nodeHasSingleChild = node.left==null || node.right==null;

        //single child
        if(nodeHasSingleChild){
            TreeNode child = node.left==null?node.right:node.left;
            if(isLeft)
                parent.left = child ;
            else
                parent.right = child;
            return root.left;
        }
        //replace with sucessor and delete successor (sucessor will exist since 2 child case - rightsubtree exists)
        //successor is always leftmost node of rightSubtree;
        int successorVal = getSucessor(node);
        // System.out.println("successor Val before" + successorVal);
        // System.out.println(node.val);
        deleteNode(root,successorVal);

        // traverseAndFindParent(root,key);

        // System.out.println("successor Val after" + successorVal);
        // System.out.println(node.val);
        node.val = successorVal;

        return root.left;
    }
}

reverse-vowels-of-a-string.code:
class Solution {
    public String reverseVowels(String s) {
        char[] sArr = s.toCharArray();
        Set<Character> vowelSet =Set.of('a','e','i','o','u','A','E','I','O','U');
        StringBuilder sb  = new StringBuilder();
        int st=0;
        int e=s.length()-1;
        while(st<e){
            boolean isVowelS =  vowelSet.contains(sArr[st]);
            boolean isVowelE =  vowelSet.contains(sArr[e]);
            if(isVowelS && isVowelE){
                //swap
                char tmp = sArr[st];
                sArr[st] = sArr[e];
                sArr[e] = tmp;
                st++;
                e--;
            } else if(!isVowelS){
                st++;
            } else{
                e--;
            }
        }
        for(char c:sArr)
            sb.append(c);

        return sb.toString();
    }
}

