class Solution {
    int[][] dp;
    int m,n;
    String text1,  text2;
    void initialize(String text1, String text2) {
        this.text1 = text1;
        this.text2 = text2;
        m = text1.length();
        n = text2.length();
        dp = new int[m][n];
        for(var ar:dp)
            Arrays.fill(ar,-1);
    }
    int lcs(int x,int y){
        if(x==-1 || y==-1)
            return 0;
        if(dp[x][y]!=-1)
            return dp[x][y];
        List<Integer> candidates = new ArrayList<>();
        if(text1.charAt(x) ==  text2.charAt(y))
            candidates.add(1+lcs(x-1,y-1));
        candidates.add(lcs(x,y-1));
        candidates.add(lcs(x-1,y));
        dp[x][y] = Collections.max(candidates);
        return dp[x][y];
    }
    public int longestCommonSubsequence(String text1, String text2) {
        initialize(text1,text2);

        return lcs(m-1,n-1);
    }
}

