class Solution {
    HashMap<String, HashMap<String,Double> > graph;
    Set<String> visited;
    double result;
    void populateGraph(List<List<String>> equations, double[] values){
        graph = new HashMap<>();
        int n = equations.size();
        for(int i=0;i<n;i++){
            List<String> equation = equations.get(i);
            String a = equation.get(0);
            String b = equation.get(1);
            double value = values[i];
            graph.putIfAbsent(a, new HashMap<>());
            graph.putIfAbsent(b, new HashMap<>());
            graph.get(a).put(b,value);
            graph.get(b).put(a,1/value);
        }
    }

    //multiply
    void dfs(String x, String b,double valueSoFar){
        if(!graph.containsKey(x))
            return;

        if(visited.contains(x))
            return;
        visited.add(x);
        if(x.equals(b)){
            result = valueSoFar;
            return;
        }

        for(String child:graph.get(x).keySet()){
            double xByChild = graph.get(x).get(child);
            dfs(child,b,valueSoFar*xByChild);
        }

    }
    public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {

        populateGraph(equations,values);
        visited = new HashSet<>();
        List<Double> results = new ArrayList<>();
        for(List<String> query: queries){

            String a = query.get(0);
            String b = query.get(1);
            //reset
            result = -1;
            visited = new HashSet<>();
            dfs(a,b,1);
            results.add(result);
        }    
        return results.stream().mapToDouble(x->x).toArray();
    }
}

nearest-exit-from-entrance-in-maze.code:
class Node{
    int x,y,step;
    public Node(int x, int y,int step){
        this.x = x;
        this.y = y;
        this.step = step;
    }

}
class Solution {
    char[][] maze;
    int[] entrance;
    boolean[][] visited;
    boolean[][] addedQueue;// optimize readding same node

    int m,n;

    void initialize(char[][] maze, int[] entrance){
        this.maze = maze;
        this.entrance = entrance;
        m = maze.length;
        n = maze[0].length;
        visited = new boolean[m][n];
        addedQueue = new boolean[m][n];
        // for(int i=0;i<m;i++)
        //     Arrays.fill(visited,fals);

    }
    boolean isValidAndUnvisited(int x,int y){
        return x>=0 && x<m && y>=0 && y<n && maze[x][y]=='.' && !visited[x][y] && !addedQueue[x][y];// optimize readding same node
    }

    List<Node> getAdj(Node node){
        int[] xOffsets = {0,0,1,-1};
        int[] yOffsets = {1,-1,0,-0};
        List<Node> adjs = new ArrayList<>(); 
        for(int i=0;i<4;i++){
            int x = node.x + xOffsets[i];
            int y = node.y + yOffsets[i];
            if(isValidAndUnvisited(x,y)){
                adjs.add(new Node(x,y,node.step+1));
            }
        }
        return adjs;
    }
    boolean isExitReached(Node node){
        int[] xOffsets = {0,0,1,-1};
        int[] yOffsets = {1,-1,0,-0};
         for(int i=0;i<4;i++){
            int x = node.x + xOffsets[i];
            int y = node.y + yOffsets[i];
            if (!(x>=0 && x<m && y>=0 && y<n))
                return true;
         }
         return false;
    }
    public int nearestExit(char[][] maze, int[] entrance) {
        Queue<Node> q = new LinkedList<>();     
        initialize(maze,entrance);
        Node root = new Node(entrance[0], entrance[1] ,0);
        q.add(root);
        while(!q.isEmpty()){
            Node current = q.poll();
            int x = current.x;
            int y= current.y;
            int step = current.step;
            // System.out.println("x:"+x+" y:"+y+ " step:"+step);
            if(isExitReached(current) && current!=root ){
                return step;
            }
            visited[x][y] = true;
            List<Node> adjs= getAdj(current);
            for(Node adj:adjs){
                q.add(adj);
                addedQueue[adj.x][adj.y] = true;  // optimize readding same node             
            }
        }
        return -1;
    }
}

