class Solution {
    int[] flowerbed;
    int len;
    boolean isFlower(int x){
        if(x>=0 && x<len)
            return (flowerbed[x]==1)? true : false;
        return false;
    }
    boolean canPlace(int x){
        return !isFlower(x-1) && !isFlower(x+1);
    }

    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        this.flowerbed = flowerbed;
        this.len = flowerbed.length;
        int count =0;
        for(int i=0;i<len;i++){
            if((flowerbed[i]==0) && canPlace(i)){
                flowerbed[i]=1;
                count++;
            }

        }
        return count >= n;
    }
}

