 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int count= 0;
    int targetSum = 0;
    List<TreeNode> nodes;
    void traverse(TreeNode x, long sumSofar){

        if(x == null)
            return;

        // System.out.println("traversing: "+x.val + " with sumSoFar " + sumSofar);
        sumSofar += x.val;
        if ( sumSofar == targetSum){
            count++;
        }

        traverse(x.left, sumSofar);
        traverse(x.right, sumSofar);       

    }
    void dfs(TreeNode x){
        if(x == null)
            return;
        //process
        nodes.add(x);
        dfs(x.left);
        dfs(x.right);

    }
    public int pathSum(TreeNode root, int targetSum) {
        this.targetSum = targetSum;
        nodes = new ArrayList<>();
        dfs(root);//populate all nodes
        for(TreeNode node:nodes)
            traverse(node,0);
        return count;
    }
}

longest-zigzag-path-in-a-binary-tree.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */

class Solution {
    int maxPath = 0;
    HashMap<TreeNode,HashMap<Character,Integer> > dp; //avoid recomputing

    int longestPath(TreeNode x, char direction, int level){
        if(x==null)
            return level;
        //if already computed return
        if(dp.containsKey(x) && dp.get(x).containsKey(direction))
            return dp.get(x).get(direction);
        //save
        dp.putIfAbsent(x, new HashMap<>());

        //process this node
        int longestPathX =0;

        if(direction == 'l')
            longestPathX = longestPath(x.left,'r',level+1);
        else
            longestPathX = longestPath(x.right,'l',level+1);


        dp.get(x).put(direction,longestPathX); 
        maxPath = Math.max(maxPath,longestPathX);
        return dp.get(x).get(direction);

    }

    public int longestZigZag(TreeNode root) {
        dp = new HashMap<>();
        //traverse all bfs
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        while(!q.isEmpty()){
            TreeNode x = q.poll();
            //process
            longestPath(x,'l',0);
            longestPath(x,'r',0);

            if(x.left!=null)
                q.add(x.left);
            if(x.right!=null)
                q.add(x.right);

        }    
        return maxPath -1;
    }
}

