class Node{
    int value; int index;
    public Node(int value, int index){
        this.value = value;
        this.index = index;
    }
}
class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] result = new int[n];
        Stack<Node> stack = new Stack<>();
        stack.add(new Node(Integer.MAX_VALUE,n));
        for(int i=n-1; i>=0;i--){
            // System.out.println(stack);
            while(!stack.empty()){
                if(stack.peek().value <= temperatures[i]){
                    // System.out.println("top value:"+ stack.peek().value+ " current:" +temperatures[i]);
                    stack.pop();
                }
                else{
                    int nextIndex = stack.peek().index;
                    result[i] = nextIndex == n?0:nextIndex - i;
                    stack.add(new Node(temperatures[i],i));
                    break;
                }
            }
        }
        return result;
    }
}

