class Solution {
    public double findMaxAverage(int[] nums, int k) {
        long maxSum = 0; 
        long sum =0;
        int n = nums.length;
        for(int i=0; i<k; i++)
            sum+=nums[i];
        maxSum = sum;
        for(int i=k;i<n;i++){
            sum = sum - nums[i-k];
            sum = sum + nums[i];
            maxSum = Math.max(maxSum, sum);
        }

        return (maxSum/(double)k);
    }
}

