class Solution {

    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] productsLeft = new int[n];
        int[] productsRight = new int[n];
        int[] result = new int[n];
        int left =1;
        int right = 1;
        for(int i=0;i<n;i++){
            left = left * nums[i];
            productsLeft[i] = left; 
        }
        for(int i=n-1; i>=0;i--){
            right = right * nums[i];
            productsRight[i] = right; 
        }
        for(int i=0; i<n; i++){
            int leftProduct = i-1 == -1?1: productsLeft[i-1];
            int rightProduct = i+1 == n? 1: productsRight[i+1];
            result[i] = leftProduct*rightProduct;
        }
        return result;
    }
}

