class StockSpanner {
    Stack<Node> stack;
    int current = 0;
    public StockSpanner() {
        stack = new Stack<>();
        stack.add(new Node(Integer.MAX_VALUE,-1));
    }

    public int next(int price) {
            int largerIndex = 0;
            while(!stack.isEmpty()){
                if(stack.peek().value <= price){
                    stack.pop(); 
                }
                else{
                    largerIndex = stack.peek().index;
                    break;
                }
            }
            stack.add(new Node(price,current));
            int span = current - largerIndex;
            current++;
            return span;
    }
}

