class Solution {
    public int longestOnes(int[] nums, int k) {

        int maxCount = 0;
        int count = 0;
        Queue<Integer> q = new LinkedList<>();
        for(int i=0 ; i< nums.length;i++){
            if(nums[i] == 1){
                count++;
            } else{
                if(q.size()<k){ //flip is possible, k to be completely consumed
                    q.add(i);
                    count++;
                }
                else{
                    if(q.size() == 0 ){ 
                        count=0;
                    }
                    else{ //reflip first 1->0 and current from 0->1
                        count = i - q.poll();
                        q.add(i);
                    }
                }
            }
            maxCount = Math.max(maxCount,count);
        }
        return maxCount;

    }
}

