class Solution {
    int[] leftSum, rightSum;
    int n;
    int getLeftSum(int x){
        if(x-1>=0)
            return leftSum[x-1];
        return 0;
    }
    int getRightSum(int x){
        if(x+1 < n)
            return rightSum[x+1];
        return 0;
    }
    public int pivotIndex(int[] nums) {
        n = nums.length;
        leftSum = new int[n];
        rightSum = new int[n];
        int left = 0;
        int right = 0 ;
        for(int i=0; i<n;i++){
            left+= nums[i];
            leftSum[i] = left;
        }
        for(int i=n-1; i>=0;i--){
            right+= nums[i];
            rightSum[i] = right;
        }

        for(int i=0; i<n;i++){
            if(getLeftSum(i) == getRightSum(i) )
                return i;
        }
        return -1;
    }
}

rotting-oranges.code:
class Node{
    int x,y,steps;
    public Node(int x, int y,int steps){
        this.x =x;
        this.y= y;
        this.steps =steps;
    }
}
class Solution {

    int m,n;
    int[][] grid;
     boolean visited[][] ;
    void initilaize(int[][] grid){
        this.grid = grid;
        m =grid.length;
        n= grid[0].length;
        visited= new boolean[m][n];
        int steps[][] = new int[m][n];
    }
    boolean checkIfFreshExists(){
         for(int i= 0 ; i<m;i++){
            for(int j=0;j<n;j++){
                if(grid[i][j] == 1){
                    return true;
                }
            }
         }
        return false;
    }
    boolean isValidAndFresh(int x, int y){
        return x>=0 && x< m && y>=0 && y<n && grid[x][y] == 1;
    }
    List<Node >getFreshOrangesNeigbours(Node current){
        List<Node> neighbours = new ArrayList<>();
        int xOffsets[] = {+1,-1,0,0};
        int yOffsets[] = {0,0,+1,-1};
        for(int i=0;i<4;i++){
            int x = current.x + xOffsets[i];
            int y = current.y + yOffsets[i];
            if(isValidAndFresh(x,y) && !visited[x][y])
                neighbours.add(new Node(x,y,0));
        }
        return neighbours;
    }
    public int orangesRotting(int[][] grid) {
        Queue<Node> q = new LinkedList<>();
        initilaize(grid);
        for(int i= 0; i<m;i++){
            for(int j=0;j<n;j++){
                if(grid[i][j] == 2)
                    q.add(new Node(i,j,0));
            }
        }
        int minSteps =0;
        while(!q.isEmpty()){
            Node current = q.poll();
            int x = current.x;
            int y = current.y;
            int steps = current.steps;
            if(visited[x][y])
                continue;
            visited[x][y] = true;
            // System.out.println("Processing:" + " x:" + x + " y:"+ y +" steps: "+ steps);
            //make this rotten
            grid[x][y] = 2;
            minSteps = steps;
            List<Node> neighbours =  getFreshOrangesNeigbours(current);
            for(Node neighbour:neighbours){
                neighbour.steps = steps+1;
                q.add(neighbour); 
            }
        }
        if(checkIfFreshExists()){
            return -1;
        }
        return minSteps;
    }
}

search-suggestions-system.code:
class TrieNode{
    boolean isLeaf;
    HashMap<Character,TrieNode> children;
    public TrieNode(){
        isLeaf = false;
        children = new HashMap<>();
    }
}
class Solution {
    TrieNode root;
    List<String> result;
    List<List<String>> fullResult;

    void insert(String product){
        TrieNode q = root;
        for(char c:product.toCharArray()){
            q.children.putIfAbsent(c, new TrieNode());
            q = q.children.get(c); 
        }
        q.isLeaf = true;
    }
    void traverse(TrieNode x, StringBuilder wordSoFar){
        // System.out.println("traversing:" + wordSoFar);
        if(result.size() == 3)
            return;
        if(x.isLeaf){
            result.add(new String(wordSoFar));
        }        
        //if no children, childrenSet will be empty
        List<Character> sortedChildren =  new ArrayList(x.children.keySet());
        sortedChildren.sort(Comparator.naturalOrder());
        for(char c:sortedChildren){
            wordSoFar.append(c);
            traverse(x.children.get(c) , wordSoFar);
            wordSoFar.deleteCharAt(wordSoFar.length()-1);
        }
    }
    void search(String searchWord){
        fullResult = new ArrayList<>();
        TrieNode q = root;
        StringBuilder wordSoFar = new StringBuilder("");
        for(char c:searchWord.toCharArray()){

            if(!q.children.containsKey(c)){

                for(int i= wordSoFar.length() ; i < searchWord.length() ;i++)
                    fullResult.add(new ArrayList<>());        
                return;
            }
            q = q.children.get(c); 
            wordSoFar.append(c);
            result = new ArrayList<>(); //reset result
            fullResult.add(result);
            traverse(q,new StringBuilder(wordSoFar));  
            // save 
            result.sort(Comparator.naturalOrder());


        }


    }
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        root = new TrieNode();
        for(String product: products){
            insert(product);
        }
        search(searchWord);
        return fullResult;

    }
}

