class Solution {
    public int maxOperations(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int sum = k;
        int s = 0;
        int e = n-1;
        int pairs = 0;
        while(s < e){
            if(nums[s] + nums[e] > sum)
                e--;
            else if(nums[s] + nums[e] < sum)
                s++;
            else{
                pairs++;
                s++;
                e--;
            }
        }   
        return pairs;
    }
}

