class Solution {
    int[][] grid;
    int n, count;
    HashMap<Integer,List<Integer>> hashCol;
    HashMap<Integer,List<Integer>> hashRow;

    void populateHashCol(){
        hashCol = new HashMap<>();
        for(int i=0;i<n;i++){
            int currentHash= 0;
            for(int j=0;j<n;j++){
                currentHash += grid[j][i];
            }
            hashCol.putIfAbsent(currentHash, new ArrayList<>());
            hashCol.get(currentHash).add(i);
        }
    }


    void populateHashRow(){
        hashRow = new HashMap<>();
        for(int i=0;i<n;i++){
            int currentHash= 0;
            for(int j=0;j<n;j++){
                currentHash += grid[i][j];
            }
            hashRow.putIfAbsent(currentHash, new ArrayList<>());
            hashRow.get(currentHash).add(i);
        }
    }
    void initialize(int[][] grid){
        this.grid = grid;
        n = grid.length;
        count = 0;
        populateHashCol();
        populateHashRow();
    }
    int iterateAndCount(){
        for(int rowKey:  hashRow.keySet()){
            List<Integer> rowList = hashRow.get(rowKey);
            List<Integer> colList = hashCol.getOrDefault(rowKey, new ArrayList<>());
            for(int rowi : rowList){
                for(int colj: colList){
                    if(match(rowi,colj))
                        count++;
                }
            }
        }
        return count;
    }
    boolean match(int row, int col){
        for(int i = 0;i<n;i++){
            if(grid[row][i] != grid[i][col])
                return false;
        }
        return true;
    }

    public int equalPairs(int[][] grid) {
        initialize(grid);
        return iterateAndCount();
    }
}

