class Solution {
    int dp[][];
    int m,n;
    void initialize(int m, int n){
        this.m = m;
        this.n= n;
        dp = new int[m][n]; 
        for(int[] row:dp)
            Arrays.fill(row,-1);
    }
    boolean isValid(int x,int y){
        return x>=0 && x<m && y>=0 && y<n;
    }
    int calculateUniquePaths(int x,int y){
        if(x== m-1 && y == n-1)
            return 1;
            if(dp[x][y] != -1)
                return dp[x][y];
        int rightPaths = isValid(x,y+1) ? calculateUniquePaths(x,y+1) :0;
        int downPaths = isValid(x+1,y) ? calculateUniquePaths(x+1,y) :0;
        dp[x][y] = rightPaths + downPaths;

        return dp[x][y];
    }
    public int uniquePaths(int m, int n) {
        initialize(m,n);
        return calculateUniquePaths(0,0);
    }
}

minimum-flips-to-make-a-or-b-equal-to-c.code:
class Solution {
    public int minFlips(int a, int b, int c) {
        int count = 0;
        while(a!=0 || b!=0 || c!=0){
            int currentA = a &1;
            int currentB = b &1;
            int currentC = c &1;

            if( (currentA | currentB) == currentC){
                //ignore
            } else{
                if(currentC == 1){
                    //implies both a, b bit 0 
                    count++;

                }else{
                    if((currentA & currentB) ==1)//if both are 1 , then flip both
                        count = count+2;
                    else //flip 1
                        count++;
                }
            }
            a = a>>1;
            b = b>>1;
            c = c>>1;
        }
        return count;
    }
}

