    int LIS(int endIdx){ //lis ending in endIdx
        if( endIdx == 0 ){
            dp[0] = 1;
            return 1;
        }
        if(dp[endIdx]!=-1)
            return dp[endIdx];
        int lis = 1;
        for(int i=0;i<endIdx; i++){
            if(nums[endIdx] > nums[i]){
                lis = Math.max(lis, LIS(i) + 1);
            }
        }
        //save
        dp[endIdx] = lis;
        return lis;
    }
    public int lengthOfLIS(int[] nums) {
        intitalize(nums);
        for(int i=0;i<n;i++){
            LIS(i);
        }
        return Arrays.stream(dp).max().getAsInt();
    }
}

