class Solution {
    HashSet<String> wordDictionary;
    String s; 
    int n;
    int dp[];
    void initialize(String s, List<String> wordDict){
        wordDictionary = new HashSet<>();
        wordDictionary.addAll(wordDict);
        this.s= s;
        this.n = s.length();
        dp = new int[n];
        Arrays.fill(dp, -1);
    }
    /*

     */
    boolean isPossible(int startIdx){
        if(startIdx == n)
            return true;
            if(dp[startIdx]!=-1){
                return dp[startIdx] == 1;
            }
        for(int i=startIdx; i<n; i++){
            String subString = s.substring(startIdx,i+1);
            if(wordDictionary.contains(subString) && isPossible(i+1)){
                dp[startIdx] = 1;
                return true;
            }
        }
        //save
        dp[startIdx] = 0;
        return false;
    }
    public boolean wordBreak(String s, List<String> wordDict) {
        initialize(s,wordDict);
        return isPossible(0);
    }
}

