 */

class TreeNodeWithParent{
    TreeNodeWithParent left; 
    TreeNodeWithParent right;
     TreeNodeWithParent parent;
     int val;
     boolean  isRight;

    public TreeNodeWithParent(int val, TreeNodeWithParent parent, boolean  isRight){
        this.parent = parent;
        this.val = val;
        this.isRight = isRight;
    }
}
class BSTIterator {
            //current node,
        //inorder in right subtree
        //if right doesn't exist  ,  find ancestor which has right subtree , leftmost node in that subtree
    TreeNodeWithParent root;
    TreeNodeWithParent currNode;

    public BSTIterator(TreeNode root) {
        this.root = getTreeNodeWithParent(root, null,true);
        this.currNode = findLeftmost(this.root);
    }
    public TreeNodeWithParent  getTreeNodeWithParent(TreeNode root,TreeNodeWithParent parent , boolean isRight) {
        if(root == null)
            return null;
        TreeNodeWithParent nodeWithParent = new TreeNodeWithParent(root.val, parent, isRight);
        nodeWithParent.left = getTreeNodeWithParent(root.left, nodeWithParent, false );
        nodeWithParent.right = getTreeNodeWithParent(root.right, nodeWithParent,true);
        return nodeWithParent;

    }
    public int next() {

        int result = currNode.val;
        if(currNode.right != null){
            // TreeNodeWithParent ancestor = findAncestorWhichRightSubtree(currNode);
            // TreeNodeWithParent iterator = ancestor.right;
            currNode = findLeftmost(currNode.right);
        } else{
             // case 2: climb up until we are coming from the left
            TreeNodeWithParent candidateChild = currNode;
            boolean found = false;

            while (candidateChild.parent != null) {
                if (!candidateChild.isRight) {
                    currNode = candidateChild.parent;
                    found = true;
                    break;
                }
                candidateChild = candidateChild.parent;
            }

            if (!found) {
                currNode = null; // end of traversal
            }
            //             // climb up using isRight safely (check parent != null first)
            // TreeNodeWithParent node = currNode;
            // while (node.parent != null && node.isRight) {
            //     node = node.parent;
            // }
            // // node.parent is the inorder successor (may be null if we were at the rightmost)
            // currNode = node.parent;


        }

        return result;
    }
    TreeNodeWithParent findLeftmost(TreeNodeWithParent iterator){
        while(iterator.left!=null){ // if iterator.left null , found the node 
            iterator = iterator.left;
        }
        return iterator;
    }

    public boolean hasNext() {
        return currNode!=null;
    }
}

