class Solution {

    public boolean isIsomorphic(String s, String t) {
        if(s.length()!=t.length())
            return false;

        //create a map , use that map
        HashMap<Character, Character> charMap = new HashMap<>();
        HashMap<Character, Character> reverseCharMap = new HashMap<>();
        for(int i=0;i<s.length();i++){
            char a = s.charAt(i);
            char b = t.charAt(i);
            if( !charMap.containsKey(a)){
                if(reverseCharMap.containsKey(b))
                    return false;

                charMap.put(a, b);
                reverseCharMap.put(b, a);
            }

            if(charMap.get(a)!= b)
                return false;
        }   
        return true;
    }
}

