class Solution {
    List<Integer>[] graph;
    int numCourses;
    void populateGraph(int[][] prerequisites) {
        // graph = new HashMap<>();
        graph = new ArrayList[numCourses];
        for (int i = 0; i < numCourses; i++) graph[i] = new ArrayList<>();
        for(int[] prerequisite:prerequisites){
            int x = prerequisite[0];
            int y = prerequisite[1];
            // graph.putIfAbsent(x, new ArrayList<>());

            graph[x].add(y);
        }     
        // System.out.println("print graph" + graph);
    }

    List<Integer> result;
    boolean visited[];
    boolean recursionStack[];

    boolean isCycle;
    void dfs(int x){
        if(visited[x])
            return;
        visited[x] =true;
        recursionStack[x] =true;
        // System.out.println("visiting:" + x);
        for(int y:graph[x]){
            if( recursionStack[y] == true){
                isCycle = true;
                return;
            }
            dfs(y);
        }
        // System.out.println("pushing:" + x);
        recursionStack[x] =false;
        result.add(x);
    }
    void populateResult(){
        visited = new boolean[numCourses];
        recursionStack = new boolean[numCourses];

        result = new ArrayList<>();
        for(int i=0; i<numCourses;i++){
            dfs(i);
        }
    }
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        //r [0, 1], indicates that to take course 0 you have to first take course 1
        // ordering of course , topological sort 0 -> 1 , 0 can be processed , when all children can be processed
        // keep a global list which pushes elements in order of processed, 
        //dfs , node is processed when all chidren 9 dependencies processed
        this.numCourses = numCourses;
        this.populateGraph(prerequisites);
        this.populateResult();

        return this.result.size() == numCourses && !isCycle ? result.stream().mapToInt(i -> i).toArray() : new int[0];
    }
}

binary-tree-level-order-traversal.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
record Node(TreeNode t, int level){}
class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        Queue<Node> queue = new LinkedList<>();
        if(root == null)
            return new ArrayList<>();

        List<List<Integer>> result = new ArrayList<>();
        List<Integer> ongoingLevelList = new ArrayList<>();

        queue.add(new Node(root,0));


        int ongoingLevel = 0;
        while(!queue.isEmpty()){
            Node currNode = queue.poll();
            //add node during processing




            //when level changes push the temporary level 
            if(currNode.level()!= ongoingLevel){
                result.add(ongoingLevelList);
                // System.out.println("---------------level changed-----------------" + result);
                //reset
                ongoingLevel ++;
                ongoingLevelList = new ArrayList<>();
            }
            ongoingLevelList.add(currNode.t().val);
            // System.out.println("Processing" + currNode.level() + " "+ongoingLevel);
            //keep adding new nodes
            if(currNode.t().left!=null){
                queue.add(new Node(currNode.t().left, currNode.level()+1));
            }
            if(currNode.t().right!=null){
                queue.add(new Node(currNode.t().right, currNode.level()+1));
            }

        }
        //push last level
        result.add(ongoingLevelList);
        return result;
    }
}

