/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    TreeNode recursivelyFlatten(TreeNode current){
        if(current ==null)
            return null;

        if (current.left == null && current.right == null) {
            return current;
        }

        // TreeNode flatCurrent = new TreeNode(current.val);
        TreeNode leftTail = recursivelyFlatten(current.left);
        TreeNode rightTail = recursivelyFlatten(current.right);
        if(leftTail!=null){
            leftTail.right = current.right;
            current.right = current.left;
            current.left = null;
        } 
        return rightTail ==null? leftTail:rightTail;
    }
    public void flatten(TreeNode root) {

        //preorder traversal of the tree
        recursivelyFlatten(root); 
    }
}

