 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    int getSize(ListNode q){
        int cnt =0;
        while(q!=null){
            cnt++;
            q= q.next;
        }
        return cnt;
    }
    ListNode getNthNode(ListNode q,int x){
        int cnt =0;
        while(q!=null && cnt!=x){

            q =q.next;
            cnt++;
        }
        return q;
    }   
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummyHead = new ListNode(-1);
        dummyHead.next = head;
        int size = getSize(head);
        int x=  size - n;
        ListNode prevNode = getNthNode(dummyHead, x);
        //perform delete
        prevNode.next = prevNode.next.next;
        return dummyHead.next;
    }
}

