class Solution {
    public boolean isValid(String s) {
        Stack<Character> stack  =new Stack<>();
        for(char c: s.toCharArray()){
            if(c =='(' || c=='[' || c=='{'){
                stack.push(c);
            } 

            else if(!stack.empty() &&  ( (stack.peek() == '(' &&c==')') || (stack.peek() == '[' &&c==']') ||   (stack.peek() == '{' &&c=='}') ) ){
                stack.pop();
            }
            else{
                return false;
            }

        }
        return stack.empty();
    }
}

