class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        // if sum is greater , keep popping from back , if sum is smaller keep adding from front , update minSubArrayLen
        int minLength = Integer.MAX_VALUE;
        int currSum = nums[0];
        int i= 0;
        int j = 0;
        int n = nums.length;
        while(true){
            // System.out.println("i:"+i+" j:"+j + " sum:" + currSum);
            if(currSum >= target){
                minLength = Math.min(j-i+1 , minLength);
                if(i>j)break;
                currSum -= nums[i];
                i++; 
            } else{
                j++;
                if(j == n)break;
                currSum = currSum + nums[j];

            }
        }
        return minLength == Integer.MAX_VALUE ? 0: minLength;
    }
}

