/*
// Definition for a Node.
class Node {
    public int val;
    public List<Node> neighbors;
    public Node() {
        val = 0;
        neighbors = new ArrayList<Node>();
    }
    public Node(int _val) {
        val = _val;
        neighbors = new ArrayList<Node>();
    }
    public Node(int _val, ArrayList<Node> _neighbors) {
        val = _val;
        neighbors = _neighbors;
    }
}
*/

class Solution {
    Set<Integer> visited = new HashSet<>();
    HashMap<Integer, Node> nodeMap = new HashMap<>();
    Node traverseAndCreateCopy(Node x){

        //need to add all edges as well
        //dont push visited children
        Node copyNode= new Node(x.val);

        visited.add(x.val);
        nodeMap.put(x.val, copyNode);
        for(Node neighbor: x.neighbors){
            Node neighbourCopy;
            if(!visited.contains(neighbor.val)){ //do not traverse
                neighbourCopy = traverseAndCreateCopy(neighbor);
            } else{
                neighbourCopy = nodeMap.get(neighbor.val);
            }
            copyNode.neighbors.add(neighbourCopy);
        }
        return copyNode;
    }
    public Node cloneGraph(Node node) {
        if(node ==null)
            return null;
        return traverseAndCreateCopy(node)    ;
    }
}

