average-of-levels-in-binary-tree.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
record Agg(long sum,long count){};

class Solution {
    HashMap<Integer, Agg> levelAgg = new HashMap<>();
    void traverse(TreeNode root, int level){
        if(root == null)
            return;
        levelAgg.putIfAbsent(level, new Agg(0, 0));
        Agg agg = levelAgg.get(level);
        levelAgg.put(level, new Agg(agg.sum() + root.val, agg.count() + 1));
        traverse(root.left, level+1);
        traverse(root.right, level+1);
    }
    public List<Double> averageOfLevels(TreeNode root) {
        traverse(root, 0);
        List<Double> avgs = new ArrayList<>();
        for(int key : levelAgg.keySet().stream().sorted().collect(Collectors.toList())){
            avgs.add( levelAgg.get(key).sum()/(double) levelAgg.get(key).count());
        }
        return avgs;
    }
}

