class Solution {
    List<List<Integer>> result = new ArrayList<>();
    int n;
    int k; 
    void generateCombination(List<Integer> currentList){//state
        int size = currentList.size();
        if(size == k){
            //save
            result.add(new ArrayList<>(currentList));
            return;
        }

        int last = size == 0? 0: currentList.get(size-1);
        for(int i = last+1 ; i<=n;i++){
            currentList.add(i);
            generateCombination(currentList);
            currentList.removeLast();
        }
    }
    public List<List<Integer>> combine(int n, int k) {
        this.n = n;
        this.k = k;
        //backtracking
        generateCombination(new ArrayList<>());
        return this.result;
    }
}

