/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode resultHead = new ListNode(-101);
        ListNode resutIterator = resultHead;



        ListNode p = list1;
        ListNode q = list2;

        while (p!=null && q!=null) {
            if(p.val < q.val){
                resutIterator.next = new ListNode(p.val);
                resutIterator = resutIterator.next;
                p = p.next;
            }else{
                resutIterator.next = new ListNode(q.val);
                resutIterator = resutIterator.next;
                q = q.next;
            }
        }
        ListNode r = p ==null?q:p;
        while(r!=null){
            resutIterator.next = new ListNode(r.val);
            resutIterator = resutIterator.next;
            r = r.next;
        }
        return resultHead.next;
    }
}

