class Solution {

    public String addBinary(String a, String b) {

        StringBuilder sbA = new StringBuilder(a);
        StringBuilder sbB = new StringBuilder(b);
        StringBuilder result = new StringBuilder();
        sbA = sbA.reverse();
        sbB = sbB.reverse();
        int carry = 0;
        int minLen= Math.min(sbA.length(), sbB.length());
        int maxLen= Math.max(sbA.length(), sbB.length());
        for(int i=0 ; i < minLen ;i++){
            int sum = (sbA.charAt(i) - '0') + (sbB.charAt(i) - '0') + carry;
            if(sum == 0){
                result.append('0');
                carry = 0;
            }else if(sum == 1){
                result.append('1');
                carry = 0;
            } else if(sum == 2){
                result.append('0');
                carry = 1;
            }else {
                result.append('1');
                carry = 1;
            }
        }
        StringBuilder remainingS = sbA.length() < sbB.length() ? sbB :sbA;
        for(int i=minLen ; i < remainingS.length()  ;i++){
            int sum = (remainingS.charAt(i) - '0')  + carry;
            if(sum == 0){
                result.append('0');
                carry = 0;

            } else if(sum == 1){
                result.append('1');
                carry = 0;

            } else{
                result.append('0');
                carry = 1;
            }
        }
        if(carry == 1)
            result.append('1');

        return result.reverse().toString();
    }
}

