rotate-list.code:
/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    int getCount(ListNode head){
        ListNode q = head;
        int cnt =0;
        while(q!=null){

            cnt++;
            q = q.next;
        }

        return cnt;
    }
    ListNode getEnd(ListNode head){
        ListNode q = head;
        while(q!=null){
            if(q.next == null){
                return q;
            }
            q = q.next;
        }
        return null;
    }
    public ListNode rotateRight(ListNode head, int k) {
    if(head ==null)
        return null;
      //traverse at the end, get end node
      //attach it to head node
      //keep traeversing till k 
      //at kth node , make k+1 as head
      //make node.next = null
        ListNode endNode = getEnd(head);
        int n = getCount(head);
        endNode.next = head;
        ListNode q = endNode;
        for(int i=0;i <n-(k%n);i++){
            q = q.next;
        }
        head = q.next; 
        q.next =null;

        return head;


    }
}

