validate-binary-search-tree.code:
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
 record NodeState(int min,int max, boolean isValid){}
class Solution {
    // left and right are valid BST subtree and  
    // track minimum in left subtree
    NodeState traverseBST(TreeNode root){
        boolean isValid = true;
        int min = root.val;
        int max = root.val;
        if(root.left != null){
            NodeState leftState = traverseBST(root.left);
            isValid = isValid && leftState.isValid() && leftState.max() < root.val;
            // System.out.println("left comparison  isValid:"+ isValid);
            min = Math.min(min , leftState.min());
        }
        if(root.right != null){
            NodeState rightState = traverseBST(root.right);
            isValid = isValid && rightState.isValid() &&  rightState.min() > root.val;
            // System.out.println("right comparison  isValid:"+  isValid + " rsMin"+ rightState.min() );

            max =Math.max(max , rightState.max());
        }
        // System.out.println( "root:" + root.val + " isValid:" + isValid);
        return new NodeState( min, max, isValid);

    }
    public boolean isValidBST(TreeNode root) {
        return traverseBST(root).isValid();
    }
}

minimum-path-sum.code:
class Solution {
    int m;
    int n;
    int dp[][];
    int grid[][];
    boolean isValid(int x,int y){
        return x>=0 && x<m && y>=0 && y<n;
    }
    int minPath(int x, int y){
        // System.out.println("x:"+x+" y:"+y);
        if(dp[x][y]!=-1)
            return dp[x][y];

        int currMinPath = Integer.MAX_VALUE;
        if(isValid(x-1, y)){
            currMinPath = Math.min(currMinPath,  minPath(x-1,y));
        }  
        if(isValid(x, y-1)) {
            currMinPath = Math.min(currMinPath,  minPath(x,y-1)) ;
        }
        //save
        dp[x][y] = grid[x][y];
        if(currMinPath != Integer.MAX_VALUE)
            dp[x][y] = currMinPath + grid[x][y];
        return dp[x][y];
    }

    public int minPathSum(int[][] grid) {
        m =grid.length;
        n = grid[0].length;
        this.grid = grid;
        dp = new int[m][n];
        for(int i=0;i<m;i++)
            Arrays.fill(dp[i], -1);

        return minPath(m-1,n-1);
    }
}

