        int start =0;
        int end = m-1;
        int mid = (start + end)/2;
        int index = m;
        while( start <= end){
            mid = (start + end)/2;
            // System.out.println("checking:" + mid + " for x:"+ x +  " product:" + potions.get(mid) * (long)x);
            if(potions.get(mid) * (long)x >=  success){
                // System.out.println("checking:" + mid + " for x:"+ x);
                index = mid; 
                end = mid-1;
            } else{
                start =mid+1;
            }
        }
        return m-index;
    }
