merge-intervals.code:
record Node(int start, int end){}
class Solution {
    List<Node> populate(int[][] intervals){
        List<Node> nodes = new ArrayList<>();
        for(int[] interval:intervals){
            nodes.add(new Node(interval[0], interval[1]));
        }
        return nodes;
    }
    public int[][] merge(int[][] intervals) {
        //sort in ascending by start
        List<Node> nodes = populate(intervals);
        nodes.sort( (x,y) -> {
            int stCmp = Integer.compare(x.start(),y.start());
            if(stCmp == 0)
                return Integer.compare(x.end(),y.end());
            return stCmp;
        });

        List<Node> mergedIntervals = new ArrayList<>();
        for(Node node:nodes){
            if(mergedIntervals.size() ==0)
                mergedIntervals.add(node);
            else{
                Node last = mergedIntervals.removeLast();
                if(last.end()>=node.start()){
                    //merge
                    int start = Math.min(last.start(),node.start());
                    int end = Math.max(last.end(),node.end());

                    mergedIntervals.add(new Node(start,end));
                }
                else{
                    mergedIntervals.add(last);
                    mergedIntervals.add(node);
                }
            }
        }

        int[][] result = new int[mergedIntervals.size()][2];
        for(int i=0;i<mergedIntervals.size();i++){
            int[] node = new int[2];
            node[0] = mergedIntervals.get(i).start();
            node[1] = mergedIntervals.get(i).end();
            result[i] = node;
        }
        return result;
    }
}

