class Node{
    int key;
    int data; 
    Node next; 
    Node previous;
    public Node(int key,int data, Node next, Node previous){
        this.key = key;
        this.data =data;
        this.next = next;
        this.previous = previous;
    }

}
class MyLinkedList{
     Node head;
    Node tail ;
    public MyLinkedList(){
        head = new  Node(-1,-1,null,null);
        tail = new Node(-1,-1,null,null);
        head.next = tail;
        tail.previous = head;

    }
    Node insertLast(int key,int data){
        Node current = new Node(key,data,null,null);
        Node previous = tail.previous;
        current.previous = previous;
        current.next = tail;
        previous.next = current;
        tail.previous = current;


        return current;
    }

    void delete(Node current){
        Node previous = current.previous;
        Node next = current.next;
        previous.next = next;
        next.previous = previous;
    }
    Node removeFirst(){

        Node current = head.next;
        if (current == tail) return null; // list is empty
        Node headNextNext = head.next.next;
        headNextNext.previous = head;
        head.next = headNextNext;
        return current;
    }

}
class LRUCache {

    /*
    Editorial java good

    cache of size c
    when we write a key,
    -- if key exists , remove key(from anywhere) and append at end of queue
    -- if key does not exists , remove from front and add key to back
    when we read a key
    -- remove key(from anywhere) and append at end of queue

    keep a hashmap key,value
    since keys are unique, we can use removeFirst(key) O(n)

     */

    //least recently used , which to remove
    // append to end of list
    int capacity;
    MyLinkedList linkedList = new MyLinkedList();

    HashMap<Integer, Node > cache;
    public LRUCache(int capacity) {
        this.capacity = capacity;
        linkedList =  new MyLinkedList();
        cache = new HashMap<>();
    }

    public int get(int key) {
        // System.out.println("Getting"+ key);
        if(cache.containsKey(key)){
            linkedList.delete(cache.get(key));
            Node current = linkedList.insertLast( key,cache.get(key).data );
            cache.put(key, current); 
            return cache.get(key).data;
        }
        return -1;
    }

    public void put(int key, int value) {
        // System.out.println("Inserting "+ key+" "+ value);
        if(cache.containsKey(key)){
            linkedList.delete(cache.get(key));
        } else if (cache.size() == capacity) {
            //remove from cache
            Node removed = linkedList.removeFirst();
            cache.remove(removed.key);

        }     
        Node current =linkedList.insertLast(key,value);
        cache.put(key,current);

        // System.out.println(linkedList +" "+ linkedList.get(0));
    }
}

/**
 * Your LRUCache object will be instantiated and called as such:
 * LRUCache obj = new LRUCache(capacity);
 * int param_1 = obj.get(key);
 * obj.put(key,value);
 */

