class Solution {
    String createEncodings(String s){
        int ar[] = new int[26];
        for(char c: s.toCharArray()){
            ar[c-'a'] ++ ;
        }
        StringBuilder encoding = new StringBuilder("");
        for(int i=0;i<ar.length;i++){
            encoding.append( (char)i+'a');
            encoding.append( ar[i]); 
        }
        // System.out.println(encoding);
        return encoding.toString();
    }
    List<List<String>> getPairs(String[] strs){
        HashMap<String ,List<Integer>> map = new HashMap<>();
        for(int i=0;i<strs.length;i++){
            String encoding = createEncodings(strs[i]);
            map.putIfAbsent(encoding,new ArrayList<>());
            map.get(encoding).add(i);
        }
        List<List<String>> results   = new ArrayList<>();
        for(String key: map.keySet()){
            List<String> anagrams = new ArrayList<>();
            for(int index: map.get(key)){
                anagrams.add(strs[index]);
            }
            results.add(anagrams);
        }
        return results;
    }
    public List<List<String>> groupAnagrams(String[] strs) {

        //rearrangement of letters
        //count letters , find the one which matches
        return getPairs(strs);
    }
}

