        int i=0;
        for(i=0;i<len;i++){
            if(left.find(nums[i]) == left.end()){
                left.insert(nums[i]);
            } else if(right.find(nums[i]) == right.end()){
                right.insert(nums[i]);
            } else{
                return false;
            }
        }

        int diff = (left.size() - right.size());
        if (diff < 0)
