class Solution {
    public boolean canArrange(int[] arr, int k) {
        // (x + x') % k ==0 Eg. 1,3 , divisible by 2
        HashMap<Integer,Integer> freq = new HashMap<>();
        for(int num:arr){
            int key = ((num % k) + k) % k;
            freq.putIfAbsent(key,0);
            freq.put(key,freq.get(key)+1);
        }

        for(int key:freq.keySet() ){
            if( (2*key == k) || key==0 ){
                if(freq.get(key)%2 != 0)
                    return false;
            }
            else if(!freq.get(key).equals(freq.getOrDefault(k-key,0)) ){
                // System.out.println("return false for key" + key + " complement key" + (k-key));
                // System.out.println("return false for key cnt" + freq.get(key) + " complement key cnt" + freq.getOrDefault(k-key,0) );
                return false;
            }
        }

        return true;
    }
}

