class Solution {
    List<String> tokenize(String s , int k){
        List<String> tokens = new ArrayList<>();
        for(int i=0; i<s.length() && i+k <=s.length();i=i+k){
            tokens.add(s.substring(i, i+k));
        }
        return tokens;
    }
    List<Integer> getAllIndexes(List<String> tokens, String[] words, int offset){
        HashMap<String, Integer> wordSet = new HashMap<>();
        for(String word:words){
            wordSet.putIfAbsent(word, 0);
            wordSet.put(word, wordSet.get(word)+1 );
        }
        int k = words.length;
        //find permutation
        //swap current with all + find permutation of words
        // if equals original string , reurn that indices
        // can parse and optimize string match
        // tokenize into lenght of words
        //create HashMap, word,index, remove,create , slifding window
        // currentSet size , if duplicates then reset from this point
        // keep just ending index
        List<Integer> result = new ArrayList<>();
        LinkedList<String> currentSet = new LinkedList<>();
        HashMap<String,Integer> currentMap = new HashMap<>();
        // System.out.println(tokens);
        for(int i=0; i<tokens.size();i++){
            // System.out.println("\nFor iteration:" + i);
            if(currentSet.size() == k){
                String removedToken = currentSet.removeFirst();
                currentMap.put(removedToken, currentMap.get(removedToken) -1);
                // System.out.println("remove i-k:" + (i-k) );
            } //remove outside sliding window

            if(wordSet.containsKey(tokens.get(i)) ){
                currentMap.putIfAbsent(tokens.get(i), 0);
                if(currentMap.get(tokens.get(i)) < wordSet.get(tokens.get(i)) ){
                    //System.out.println("Add word in set set:" +tokens.get(i));
                    //do nothing
                }
                else{
                    while(true){
                        String removedToken = currentSet.removeFirst();
                        currentMap.put(removedToken, currentMap.get(removedToken) -1);
                        if(currentMap.get(tokens.get(i)) < wordSet.get(tokens.get(i))){
                            break;
                        }
                    }
                }

                currentSet.add(tokens.get(i));
                // System.out.println(currentMap);
                currentMap.putIfAbsent(tokens.get(i), 0);
                currentMap.put(tokens.get(i), currentMap.get(tokens.get(i)) +1);
            }
            else{

                currentMap.clear();
                currentSet.clear();
            }
            // System.out.println(currentMap);
            if(currentSet.size() == k){
                // System.out.println("set size reached.. adding:" +(i-k+1) );
                result.add( (i-k+1) *words[0].length() +offset );
            }
        }
        return result;

    }
    public List<Integer> findSubstring(String s, String[] words) {

        Set<Integer> result = new HashSet<>();
        for(int i=0; i< words[0].length() && i <s.length() ;i++){
            List<String> tokens = tokenize(s.substring(i), words[0].length());
            result.addAll(getAllIndexes(tokens, words, i));
        }
        return result.stream().toList();

    }
}

