class Solution {
    int[] toDigits(String num){
        int[] digits = num.chars().map(c -> c - '0')  // custom mapping function
    .toArray();
    return digits;

    }
    List<List<Integer>> getList(String num1, String num2){
        num1 = new StringBuilder(num1).reverse().toString();
        num2 = new StringBuilder(num2).reverse().toString();
        int[] digits1 = toDigits(num1);
        int[] digits2 = toDigits(num2); 
        List<List<Integer>> numList = new ArrayList<>();
        int factor =0;
        for(int digit1: digits1){
            int carry = 0;
            List<Integer> list = new ArrayList<>();
            // append 0's at start
            IntStream.range(0,factor).forEach(
                x -> list.add(0)
            );

            for(int digit2:digits2){
                int total = carry + digit1* digit2;
                list.add(total%10); // add only current digit1
                carry = total/10;
            }
            factor=factor+1;
            if(carry!=0)
                list.add(carry);
            numList.add(list);
        }



        return numList;

    }
    String performSum(List<List<Integer>> multiList){


        int carry= 0;
        int maxSize = 0;
        List<Integer> result = new ArrayList<>();

        for(List<Integer> list: multiList)
            maxSize = Math.max(maxSize,list.size());

        for(int i=0 ;i <maxSize ;i++){
            int total = 0;
            //sum ith digit for all
            for(List<Integer> list:multiList){
                if(i >= list.size())
                    continue;
                total+=list.get(i);
            }
            total = total+ carry;
            result.add(total%10);
            // System.out.println("carry" + carry);
            carry = total/10;
        }
        while(carry!=0){
            result.add(carry);
            carry = carry/10;
        }
        StringBuilder resultS = new StringBuilder("");
        for(int digit : result)
            resultS.append(digit);
        while(resultS.charAt(resultS.length() -1) == '0')
            resultS.deleteCharAt(resultS.length() -1);

        resultS.reverse();
        return resultS.toString();
    }

    public String multiply(String num1, String num2) {
        //perform multipication num1,num2      
        // reverse both num1, num2
        //iteration i :  multiply ith number in num2 with all num1 push into list , 
        // sum from i and carry forward , return final List of integers and convert them  to characters
        if(num1.equals("0") || num2.equals("0") ) 
            return "0";
        List<List<Integer>> lists =getList(num1,num2);
        // System.out.println("all list" +lists);
        return performSum(lists);

    }
}

sliding-window-maximum.code:
record Node(int data, int index){}
class MyComparator implements Comparator<Node>{
    public int compare(Node x, Node y){
        if(x.data() == y.data())
            return x.index() - y.index();
        return y.data() - x.data() ;
    }


}
class Solution {

    public int[] maxSlidingWindow(int[] nums, int k) {

        //heap , push 
        // find a node and delete , BST, treeSet
        TreeSet<Node> queue = new TreeSet<>( new MyComparator());
        int n = nums.length;
        int[] result = new int[n-k+1];        
        for(int i=0; i<k; i++){
            queue.add(new Node(nums[i], i));
        }
        result[0] = queue.iterator().next().data();
        for(int i=k; i<n; i++){
            int data = nums[i-k];
            queue.remove(new Node(data,i-k));  // this works, deleteing a specific node in priority queue or any collection
            queue.add(new Node(nums[i], i));
            result[i-k+1] = queue.iterator().next().data();
        }
        return result;
    }
}

