class Solution {
    public int maximumProduct(int[] nums) {
        List<Integer> list =  new ArrayList<>(Arrays.stream(nums).boxed().toList());
        list.sort((x,y) -> x-y);
        int n =list.size();
        return Math.max(list.get(0)*list.get(1) * list.get(n-1) ,  
        list.get(n-1) * list.get(n-2)*list.get(n-3));                
    }
}

