class Solution {

    boolean isPossible = false;
    List<Double> evaluate2(double x,double y){
        List<Double> list  = new ArrayList<>();
        list.add(x*y);
        list.add(x-y);
        list.add(y-x);
        if (y != 0) list.add(x / y);
        if (x != 0) list.add(y / x);
        list.add(x+y);
        return list;
    }
    List<List<Double>> getAllChildren(List<Double> processedSoFar){
        int n = processedSoFar.size();
        List<List<Double>> children = new ArrayList<>();
        for(int i=0; i<n;i++){
            for(int j = i+1; j<n;j++){
                List<Double> operationsXY = evaluate2(processedSoFar.get(i), processedSoFar.get(j) );
                List<Double> childList = new ArrayList<>();
                for(int k =0 ;k < n;k++ ){
                    if(i!=k && j!=k ) childList.add(processedSoFar.get(k));
                }
                for(double operation : operationsXY){
                    List<Double> tmpList = new ArrayList<>(childList);
                    tmpList.add(operation);
                    children.add(tmpList);
                }
            }
        }
        return children;

    }
    void process(List<Double> processedSoFar){

        if(isPossible)
            return;
        if(processedSoFar.size() == 1 ){
            // System.out.println(processedSoFar.get(0));
            if(Math.abs(processedSoFar.get(0) - 24.0 ) <=0.1){
                isPossible = true;
                return;
            }
        }
        List<List<Double>> children =   getAllChildren(processedSoFar);
        for(List<Double> child: children)
            process(child);
    }
    public boolean judgePoint24(int[] cards) {
        // pick any two , compute , create new list , and push at end (do this for all child)
        // repeat till size is 1
        isPossible = false;
        process(new ArrayList<Double>(Arrays.asList(
    (double) cards[0],
    (double) cards[1],
    (double) cards[2],
    (double) cards[3]
)));
        return isPossible;

    }
}

