record Node(String mutation, int count){

}
class Solution {
    //HashSet , bank
    //for string , 
    //mutate by exactly 1, --> get NeighbourSet
    //if valid and is unvisited then push 
    HashSet<String> bankSet ;
    HashSet<String> visited ;

    HashSet<Node> getUnvisitedNeigbourSet(Node current){
        HashSet<Node> neigbourSet = new HashSet<>();
        String mutation = current.mutation();
        char []choices = {'A','C','G','T'};
        for (int i = 0; i < mutation.length();i++) {
            for(char c: choices){
                StringBuilder newMutationSb = new StringBuilder(mutation);
                newMutationSb.setCharAt(i, c);
                String newMutation = newMutationSb.toString();
                if(bankSet.contains(newMutation) && !visited.contains(newMutation)){
                    neigbourSet.add(new Node(newMutation, current.count() + 1));
                }
            }            
        }
        return neigbourSet;
    }

    public int minMutation(String startGene, String endGene, String[] bank) {
        bankSet = new HashSet<>(List.of(bank));
        visited = new HashSet<>();
        Queue<Node> queue = new LinkedList<>();
        queue.add(new Node(startGene,0)); 
        while(!queue.isEmpty()){
            Node current = queue.poll();
            visited.add(current.mutation());
            if(current.mutation().equals(endGene))
                return current.count();
            HashSet<Node> neighbourSet = getUnvisitedNeigbourSet(current);
            for(Node neighbour:neighbourSet){
                queue.add(neighbour);
            }

        }  
        return -1;            
    }
}

