class H2O {
    // switch between hydrogen and oxygen
    // oxygen and oxygen
    // if state is O1 -> change state to O2 , condition


    Lock lock = new ReentrantLock();
    Condition hydrogenController = lock.newCondition();
    Condition oxygenController = lock.newCondition();
    int oxygenCnt = 0;
    int hydrogenCnt = 0;

    public H2O() {

    }

    public void hydrogen(Runnable releaseHydrogen) throws InterruptedException {

        // releaseHydrogen.run() outputs "H". Do not change or remove this line.
        lock.lock();
        try {
            while (hydrogenCnt == 2) {//capacity full
                hydrogenController.await();
            }
            releaseHydrogen.run();
            hydrogenCnt++;
            if (hydrogenCnt == 2 && oxygenCnt == 1) {
                //reset
                hydrogenCnt = 0;
                oxygenCnt = 0;
            }
            if(hydrogenCnt < 2){
                hydrogenController.signal();
            }
            if(oxygenCnt <1){
                oxygenController.signal();
            }
        } finally {
            lock.unlock();
        }
    }

