class ZeroEvenOdd {
    private int n;
    Lock lock = new ReentrantLock();
    Condition zeroController = lock.newCondition();
    Condition oddController = lock.newCondition();
    Condition evenController = lock.newCondition();
//    Condition oddEvenController = lock.newCondition();
    boolean isZero = true;
    boolean isOdd = true;
    public ZeroEvenOdd(int n) {
        this.n = n;
    }

    // one variable to alternate zero, odd/even , lock 0 , unlock odd/even
    // one variable to alternate between odd/even,
    // all threads share same lock
    // - zero block  unblock odd/even
    // - odd wait on isOdd, unset even  , unblock zero, unset even,
    // isEvenCondn, isOddCondn

    // printNumber.accept(x) outputs "x", where x is an integer.
    public void zero(IntConsumer printNumber) throws InterruptedException {
        for(int i = 0; i< n ;i++){
            lock.lock();
            try{
//                System.out.println("Zero thread started");
                while (!isZero) {
//                    System.out.println("waiting on zero");
                    // oddController.signal();
                    // evenController.signal();
                    zeroController.await();
                }
                printNumber.accept(0);
                isZero = false; //shift control to zero thread
                oddController.signal();
                evenController.signal();
            }finally {
                lock.unlock();
            }
        }
    }

    public void even(IntConsumer printNumber) throws InterruptedException {
        for(int i = 0; i<n/2 ;i++){
            lock.lock();
            try{
//                System.out.println("even thread started");

                while (isZero) {
//                    System.out.println("Even thread waiting on not zero");

                    // zeroController.signal();
                    evenController.await();
                }
                while (isOdd) {
//                    System.out.println("thread waiting is even flag");

                    // oddController.signal();
                    evenController.await();
                }
                printNumber.accept(i*2+2);
                isZero = true; //shift control to zero thread
                isOdd = true;
                zeroController.signal();
            }finally {
                lock.unlock();
            }

        }
    }

    public void odd(IntConsumer printNumber) throws InterruptedException {

        for(int i = 0; i<(n+1)/2 ;i++){
            lock.lock();
            try{
//                System.out.println("odd thread started");

                while (isZero) {
//                    System.out.println("Odd thread waiting on not zero");

                    // zeroController.signal();
                    oddController.await();
                }
                while (!isOdd) {
//                    System.out.println("thread waiting is odd flag");
                    // evenController.signal();
                    oddController.await();
                }
                printNumber.accept(i*2+1);
                isZero = true; //shift control to zero thread
                isOdd = false;
                zeroController.signal();
            }finally {
                lock.unlock();
            }
        }
    }

    public static void main(String[] args) {
        ZeroEvenOdd zeroEvenOdd = new ZeroEvenOdd(2);
        IntConsumer printNumber = value -> System.out.println(value);
        Runnable r1 = () -> {
            try {
                zeroEvenOdd.zero(printNumber);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        };
        Runnable r2 = () -> {
            try {
                zeroEvenOdd.odd(printNumber);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        };
        Runnable r3 = () -> {
            try {
                zeroEvenOdd.even(printNumber);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        };

        new Thread(r1).start();
        new Thread(r2).start();
        new Thread(r3).start();

    }
}

