    Trie trie = new Trie();
    ArrayList<String> results = new ArrayList<>();
    char[][] board;
    boolean isValid(int x, int y){
        return x>=0 && x < n && y>=0 && y<m;
    }

    void createTrie(String[] words){
        for(int i=0; i< words.length;i++){
            this.trie.insert(words[i]);
        }
    }
    void dfs(Trie trieSoFar, int x, int y, String wordSoFar){
        if(!isValid(x,y) || visited[x][y])
            return;
        ;
        visited[x][y] = true;
        char c = board[x][y];
        if(trieSoFar.nodes.containsKey(c)){

            wordSoFar += c;
            // System.out.println(wordSoFar);
            // System.out.println("is last" + trieSoFar.nodes.get(c).isLast);

            if(trieSoFar.nodes.get(c).isLast){
                // System.out.println("found word"+wordSoFar);
                results.add(wordSoFar);
            }
            dfs(trieSoFar.nodes.get(c),x+1,y, wordSoFar);
            dfs(trieSoFar.nodes.get(c),x-1,y, wordSoFar);
            dfs(trieSoFar.nodes.get(c),x,y+1, wordSoFar);
            dfs(trieSoFar.nodes.get(c),x,y-1, wordSoFar);
        }
        visited[x][y] = false;


    }

    public List<String> findWords(char[][] board, String[] words) {
        n = board.length;
        m = board[0].length;
        visited = new boolean[n][m];
        this.board = board;
        createTrie(words);
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                //reinitialize
                // visited = new boolean[n][m];
                dfs(trie,i,j,"");
            }
        }
        return new ArrayList(new HashSet<String>(results));
    }
}

