/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
   boolean isLeaf(TreeNode root){
        if(root == null)
            return true;
        return root.left == null && root.right == null;
    }
    int height(TreeNode root){
        int leftHeight = root.left ==null ? 0 : height(root.left);
        int rightHeight = root.right == null? 0 : height(root.right);
        int currHeight = 1 + Math.max(leftHeight,rightHeight);
        // System.out.println("height:"+ (root.val+" --> ") + currHeight);
        return currHeight;
    }
    public boolean isBalanced(TreeNode root) {
        if(root==null || isLeaf(root))
            return true;
        boolean isLeftBalanced =  isBalanced(root.left);
        boolean isRightBalanced = isBalanced(root.right);
        int leftHeight = root.left ==null ? 0 : height(root.left);
        int rightHeight = root.right == null? 0 : height(root.right);
        boolean isBalanced =  isLeftBalanced && isRightBalanced && (Math.abs(leftHeight - rightHeight) <=1);
        // System.out.println("isBalanced:"+ (root.val+" --> ") + isBalanced+ "isLeftBalanced:"+isLeftBalanced+ "isRightBalanced:"+ isRightBalanced );
        return isBalanced;
    }
}

coin-change.code:
class Solution {
    // take this coin + fewest among rest minCoin(sum - coin[j],j)
    // dont take and fewest among rest minCoin(sum,j-1)
    // min steps to make sum 0 is 1
    int[] coins;
    int amount;
    int dp[][];
    int n;

    void initialize(){
        dp = new int[amount+1][n];
        for(int[] e: dp){
            Arrays.fill(e,-2);
        }
    }

    int minCoin(int sum , int j){
        if(sum < 0 || j < 0 )
            return Integer.MAX_VALUE; // not possible
        if(sum == 0){
            dp[sum][j]  = 0;
        }
        if(dp[sum][j]!=-2)
            return dp[sum][j];

        int left = minCoin(sum - coins[j],j);
        int right =  minCoin(sum,j-1);
        dp[sum][j] = right;
        if(left!=Integer.MAX_VALUE && left + 1 < right)
            dp[sum][j] = left + 1;
        return dp[sum][j];
    }
    public int coinChange(int[] coins, int amount) {
        this.coins = coins;
        this.amount = amount;
        this.n = coins.length;
        initialize();
        int value = minCoin(amount, n-1);
        if(value == Integer.MAX_VALUE)
            return -1;
        return value;
    }

}

