class Solution {
public:
    vector<int> calcLps(string sub)
    {
        int n=sub.size();
        vector<int> lps(n);
        int i=0;
        int j=1;
        lps[0]=-1;
        //i is compared with j ... if it equals i is the proper prefix which matches j
        while(j<n){
            //cout<<i<<" "<<j<<endl;
            if(sub[i]==sub[j]){
                lps[j]=i;   //jth matched with ith store next index
                i++;
                j++;
            }
            //sub[i]!=sub[j]
                //i==0
            else if(i==0){ //jth not matched with ith
                lps[j]=-1;//matches with nothing i remains 0
                j++;        
            }
            //if sub[i]!=sub[j] try 
            else{//if j doesnt match find smaller prefix
                i=lps[i-1]+1;// if this prefix not matched ....find longest prefix which was matched till i;
            }
        }

        return lps;
    }



    int findSub(string s,string sub)
    {
        vector<int> lps=calcLps(sub);
        //cout<<"lps calculated..."<<endl;
        int m=s.size();
        int n=sub.size();
        int i=0;//substring pointer
        int j=0;//j string pointer
        while (j<m)
        {
            if(sub[i]==s[j]){
                i++;
                if(i==n)
                    return j-n+1;
                j++;
            }
            //and sub[i]!=s[j] //substring does not match with first character
            else if(i==0){
                j++;
            }
            else{
                i=lps[i-1]+1;//match smaller prefix
            }
        }

        return -1;
    }
    int strStr(string haystack, string needle) {
        if(needle=="")
            return 0;
        else if(haystack=="")
            return -1;
        return findSub(haystack,needle);
    }
};

