 * };
 */
class Solution {
public:
    int maxd=-1;

    int dfs(TreeNode* root)
    {
        if(root == NULL)
            return 0;

        int left=dfs(root->left);
        int right=dfs(root->right);

        int curr=left+right+1;
        maxd=max(maxd,curr);
        return max(left+1,right+1);

    }

    int diameterOfBinaryTree(TreeNode* root) {
        if(root==NULL)
            return 0;
        dfs(root);
        return maxd-1;
    }
};

