        vector<int> lps(n);
        int i=0;
        int j=1;

        while(j<n){
            if(sub[i]==sub[j]){
                lps[j]=i+1;
                i++;
                j++;
            }
            else if(i==0){
                lps[j]=0;
                j++;        
            }
            else{
                i=lps[i-1];// if this prefix not matched ....find longest prefix which was matched till i;
            }
        }

        return lps;
    }

    string shortestPalindrome(string s) {
        string rev(s);
        reverse(rev.begin(),rev.end());
        int m=s.size();

        s=s+"$"+rev;
        int n=s.size();
        // cout<<s<<endl;
        vector<int> lps=calcLps(s);

        string add(s.begin()+lps[n-1],s.begin()+m);
        reverse(add.begin(),add.end());
        string rem(s.begin(),s.begin()+m);
        return add+rem;
    }
};

redundant-connection.code:
class Solution {
public:
    struct my_set
    {
        int parent;
        int size;

        my_set()
        {
            this->parent=-1;
            this->size=1;   
        }

        my_set(int parent,int size)
        {
            this->parent=parent;
            this->size=size;
        }
    };

    vector<my_set> sets;
    int findSet(int x)
    {
        while(sets[x].parent!=-1)
            x=sets[x].parent;

        return x;
    }

    void unionBySize(int x,int y)
    {
        x=findSet(x);
        y=findSet(y);

        if(sets[x].size < sets[y].size){
            sets[y].size+=sets[x].size;
            sets[x].parent=y;
        }
        else{
            sets[x].size+=sets[y].size;
            sets[y].parent=x;
        }
    }



    vector<int> findRedundantConnection(vector<vector<int>>& edges) {
        vector<int> result;
        int n=edges.size();
        sets.clear();
        sets.resize(n+1);
        for(auto edge:edges){
            int u=edge[0];
            int v=edge[1];
            if(findSet(u)==findSet(v)){
                result.push_back(u);
                result.push_back(v);
                return result;
            }

            unionBySize(u,v);
        }
    }
};

