class Solution {
public:
    int maxl=0;
    int calclongestUnivaluePath(TreeNode* root)
    {
        if(root==NULL)
            return 0;

        int l=root->left?calclongestUnivaluePath(root->left):0;
        int r=root->right?calclongestUnivaluePath(root->right):0;

        int incl=root->left?(root->val==root->left->val?1+l:0):0;
        int incr=root->right?(root->val==root->right->val?1+r:0):0;

        maxl=max(maxl,incl+incr);

        return max(incl,incr);
    }
    int longestUnivaluePath(TreeNode* root) {

        calclongestUnivaluePath(root);
        return maxl;
    }
};

