class Solution {
    StringBuilder appendNTimes(StringBuilder sb, String symbol,int times){
        for(int i=0;i<times;i++)
            sb.append(symbol);
        return sb;
    }
    public String intToRoman(int num) {
        StringBuilder sb = new StringBuilder("");
        HashMap<Integer,String> valueSymbols =  new HashMap(Map.ofEntries(
                Map.entry(1000, "M"),
                Map.entry(900, "CM"),
                Map.entry(500, "D"),
                Map.entry(400, "CD"),
                Map.entry(100, "C"),
                Map.entry(90, "XC"),
                Map.entry(50, "L"),
                Map.entry(40, "XL"),
                Map.entry(10, "X"),
                Map.entry(9, "IX"),
                Map.entry(5, "V"),
                Map.entry(4, "IV"),
                Map.entry(1, "I")
            ));
        List<Integer> valueSymbolsSorted = valueSymbols.keySet().stream().collect(Collectors.toList());
        valueSymbolsSorted.sort(Comparator.reverseOrder());
        for(var key:valueSymbolsSorted){
            int quotient=num/key;
            sb = appendNTimes(sb,valueSymbols.get(key), quotient); 
            num = num% key;
        }
        return sb.toString();
    }
}

