find-first-and-last-position-of-element-.code:
class Solution {
    int getFirstElement(int[] nums, int target){
        int n = nums.length;
        int start = 0;
        int end = n-1;
        int candidate =-1;
        while(start <= end){
            int mid = (start+end)/2;
            if(nums[mid] == target){
                candidate = mid;
                //keep finding to left 
                end = mid-1;
            }
            else if(target < nums[mid]){
                end = mid -1;
            }
            else{
                start = mid+1;
            }
        }
        return candidate;

    }
    int getLastElement(int[] nums, int target){
        int n = nums.length;
        int start = 0;
        int end = n-1;
        int candidate =-1;
        while(start <= end){
            int mid = (start+end)/2;
            if(nums[mid] == target){
                candidate = mid;
                //keep finding to right 
                start = mid+1;
            }
            else if(target < nums[mid]){
                end = mid -1;
            }
            else{
                start = mid+1;
            }
        }
        return candidate;
    }
    public int[] searchRange(int[] nums, int target) {
        int firstElement = getFirstElement(nums,target);
        int lastElement = getLastElement(nums,target);
        int[] result = new int[2];
        result[0] = firstElement;
        result[1] = lastElement;
        return result;
    }
}

largest-rectangle-in-histogram.code:
class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int[] nums = heights;
        var stack = new Stack<Integer>();
        var smallerElementLeft = new int[n];
        for(int i=0;i<n;i++){
            int currentElement = nums[i];
            smallerElementLeft[i] = -1;
            while(!stack.empty()){
                if(nums[stack.peek()] < currentElement) {
                    smallerElementLeft[i] = stack.peek();
                    break;
                }               
                stack.pop();
            }
            stack.add(i);  
        }

        var smallerElementRight = new int[n];
        stack = new Stack<Integer>();
        for(int i=n-1;i>=0;i--){
            int currentElement = nums[i];
            smallerElementRight[i] = n;
            while(!stack.empty()){
                if(nums[stack.peek()] < currentElement) {
                    smallerElementRight[i] = stack.peek();
                    break;
                }               
                stack.pop();
            }
            stack.add(i);  
        }
        int maxRectangle = 0;
        for(int i=0;i<n;i++){
            int height = nums[i];
            int leftIndex = smallerElementLeft[i] + 1;
            int rightIndex = smallerElementRight[i] -1;
            int currentRectangle = (i -leftIndex+1)*height + (rightIndex -i +1)*height - height;
            maxRectangle = Math.max(currentRectangle,maxRectangle) ;

        }
        return maxRectangle;
    }
}

