/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    int getCount(ListNode head){
        ListNode q =head;
        int count =0;
        while(q!=null){
            count++;
            q = q.next;
        }
        return count;
    }

    ListNode getPreMid(ListNode head, int count){

        ListNode q =head;
        int midCount = count/2;         
        for(int i=2;i<=midCount;i++){
            q=q.next;
        }
        return q;
    }
    ListNode reverse(ListNode preHead){
        if(preHead.next==null)
            return null;

        ListNode p = preHead.next;
        ListNode q = p.next;
        p.next = null;
        var newMid = p;

        while(q!=null){
            ListNode tmp = q.next;
            q.next = p;
            //update for next iteration
            p=q;

            q= tmp;
        }

        newMid = p;
        // preHead.next = newMid;

        return newMid;

    }
    public void reorderList(ListNode head) {
        if(head.next ==null)
            return;
        var preHead = new ListNode(-1); 
        int count = getCount(head);
        ListNode midPreNode = getPreMid(head, count);
        System.out.println("premid:" + midPreNode.val);
        ListNode newMidNode = reverse(midPreNode);
        // midPreNode.next = newMidNode;
        ListNode p = head;
        ListNode q = newMidNode;
        ListNode m = preHead;
        while(p!=null){
            if(q.next == null){
                m.next = p;
                break;
            }
            ListNode ptmp = p.next;

            ListNode qtmp = q.next;

            m.next = p;
            p.next = q;
            m = q;

            p =  ptmp;
            q = qtmp;


        }


        head = preHead.next;
    }
}

