 *         this.right = right;
 *     }
 * }
 */


class Solution {
    Map<TreeNode,Integer> countNodes= new HashMap<>();  
     int getCountAndStore(TreeNode x){
        if(x ==null) 
            return 0;
        int currentCount = 1 + getCountAndStore(x.left) + getCountAndStore(x.right);
        countNodes.put(x,currentCount);
        return currentCount;
    }
    public int kthSmallest(TreeNode root, int k) {
        TreeNode q =root;
        int remaining = k;
        getCountAndStore(root);
        while(q!=null){
            int leftCount = q.left!=null ? countNodes.get(q.left): 0;

            if( (leftCount+1) == remaining)
                return q.val;//node found
            else if(leftCount < remaining){
                q = q.right;
                remaining = remaining - (leftCount+1); 
            }
            else
                q= q.left;
        }
        return -1;
    }
}

