class Solution {
    HashMap<Boolean,Integer>[] dp;
    int[] prices;
    int fee;
    int n;
    void initialize(int[] prices, int fee){
        this.prices = prices;
        this.n = prices.length;
        this.fee = fee;
        dp = new HashMap[n+1];
        for(int i=0;i<n;i++){
            dp[i] = new HashMap();
            dp[i].put(true,-1);
            dp[i].put(false,-1);
        }

    }
    int maxProfitCalculate(int x,boolean hold){
        if(x == n)
            return 0;
        if(dp[x].get(hold)!=-1)
            return dp[x].get(hold);

        if(hold == false){
            int currentMaxProfit = Math.max(
                maxProfitCalculate(x+1,false),
                -prices[x] + maxProfitCalculate(x+1,true)
            );
            dp[x].put(hold,currentMaxProfit);
        } else{
            int currentMaxProfit = Math.max(
                maxProfitCalculate(x+1,true),
                prices[x] - fee + maxProfitCalculate(x+1,false)
            );
            dp[x].put(hold,currentMaxProfit);
        }
        return dp[x].get(hold);
    }
    public int maxProfit(int[] prices, int fee) {
        initialize(prices,fee);
        return maxProfitCalculate(0,false);
    }
}
